/** Authored school materials. Quarter assignments are teaching suggestions, not an
 * official calendar or human editorial approval. No assessment-paper content. */
import type {Topic,Task,Bilingual,BilingualSteps,Example} from './content';

export type SchoolAdvancedMetadata={topicId:string;grade:5|6|7|8|9|10|11;pathway:'common'|'natural-math';quarter:1|2|3|4;quarterStatus:'author-suggestion';appendix:52|53|54|104|106;alternateAppendices?:number[];source:string;checkedAt:string};
const b=(ru:string,kk:string):Bilingual=>({ru,kk});
const bs=(...s:Bilingual[]):BilingualSteps=>({ru:s.map(v=>v.ru),kk:s.map(v=>v.kk)});
const f=(n:number)=>Number(n.toFixed(8)).toString();
type Draft=Omit<Task,'id'|'topicId'|'level'|'skill'|'commonError'>;
type Definition={id:string;grade:SchoolAdvancedMetadata['grade'];pathway:SchoolAdvancedMetadata['pathway'];quarter:SchoolAdvancedMetadata['quarter'];appendix:SchoolAdvancedMetadata['appendix'];alternateAppendices?:number[];pre:string[];title:Bilingual;goal:Bilingual;theory:Bilingual;formula:Bilingual;terms:Bilingual;method:Bilingual;why:Bilingual;use:Bilingual;error:Bilingual;build:(n:number,l:1|2|3)=>Draft};
const num=(prompt:Bilingual,answer:number,steps:Bilingual[],hint:Bilingual):Draft=>{if(Math.abs(answer-Number(answer.toFixed(6)))>1e-9)prompt=b(`${prompt.ru} Округли до 6 знаков после запятой.`,`${prompt.kk} Үтірден кейінгі 6 таңбаға дейін дөңгелекте.`);return {type:'number',prompt,answer:f(answer),tolerance:1e-6,solution:bs(...steps),hints:bs(hint,steps[0],b('Проверь результат в исходном условии.','Нәтижені бастапқы шартпен тексер.'))};};
const choice=(prompt:Bilingual,answer:string,options:string[],steps:Bilingual[],hint:Bilingual):Draft=>({type:'single',prompt,answer,options,solution:bs(...steps),hints:bs(hint,steps[0],b('Проверь, какие условия отсутствуют у остальных вариантов.','Басқа нұсқаларда қандай шарт жоқ екенін тексер.'))});
const many=(prompt:Bilingual,answer:string[],options:string[],steps:Bilingual[],hint:Bilingual):Draft=>({...choice(prompt,'',options,steps,hint),type:'multiple',answer});
const match=(prompt:Bilingual,pairs:{left:string;right:string}[],options:string[],steps:Bilingual[],hint:Bilingual):Draft=>({...choice(prompt,'',options,steps,hint),type:'matching',pairs,answer:pairs.map(p=>p.right)});
const definitions:Definition[]=[
 {
  id:'school-constructions',grade:5,pathway:'common',quarter:4,appendix:52,pre:['school-basic-angles','school-number-ray'],title:b('Построения: транспортир и циркуль','Салу: транспортир және циркуль'),
  goal:b('Строить угол по градусной мере и окружность с заданным центром и радиусом, проверяя настройку инструмента.','Градус өлшемі бойынша бұрыш пен берілген центрі, радиусы бар шеңбер салу, құрал баптауын тексеру.'),
  theory:b('Транспортир измеряет угол, циркуль переносит длину. Для угла начерти первый луч, совмести центр транспортира с вершиной и нулевую отметку выбранной шкалы с лучом. Выбери шкалу, где у этого луча стоит 0, отметь нужный градус и проведи второй луч. Отсчёт от 180 вместо 0 даёт дополнительный угол — частую ошибку. Чтобы разделить известный угол пополам транспортиром, делим его градусную меру на 2; это измерительное построение. Для окружности выбери центр O, установи раствор циркуля равным радиусу и проведи полный оборот, сохраняя иглу в O. Радиус — расстояние от центра до любой точки окружности; диаметр проходит через центр и вдвое длиннее. Точная геометрическая конструкция без измерений, например биссектриса только циркулем и линейкой, требует отдельного доказательства и относится к следующему этапу обучения.','Транспортир бұрышты өлшейді, циркуль ұзындықты көшіреді. Бұрыш үшін бірінші сәулені сыз, транспортир центрін төбемен, таңдалған шкаланың нөлдік белгісін сәулемен беттестір. Осы сәуледе 0 тұрған шкаланы таңда, керек градусты белгілеп, екінші сәулені жүргіз. 0 орнына 180-нен санау қосымша бұрыш береді — жиі қате. Белгілі бұрышты транспортирмен тең бөлу үшін градус өлшемін 2-ге бөлеміз; бұл өлшеу арқылы салу. Шеңбер үшін O центрін таңда, циркуль ашылуын радиусқа теңдеп, инені O-да сақтап толық айналдыр. Радиус — центрден шеңбердің кез келген нүктесіне қашықтық; диаметр центр арқылы өтіп, екі есе ұзын. Өлшеусіз дәл геометриялық салу, мысалы тек циркуль мен сызғышпен биссектриса, бөлек дәлелдеуді талап етеді және келесі оқу кезеңіне жатады.'),
  formula:b('Половина угла β=α/2; диаметр d=2r. α,β — градусы, r>0 — радиус, d — длина диаметра.','Бұрыштың жартысы β=α/2; диаметр d=2r. α,β — градус,r>0 — радиус,d — диаметр ұзындығы.'),terms:b('Раствор циркуля — расстояние между ножками; вершина — общий конец лучей; радиус и диаметр измеряются в единицах длины.','Циркуль ашылуы — аяқтары арасы; төбе — сәулелердің ортақ ұшы; радиус пен диаметр ұзындық бірліктерімен өлшенеді.'),method:b('Назови требуемую величину и инструмент. Для угла проверь центр и ноль шкалы; для окружности — неподвижный центр и раствор. Проверь градусы или расстояние после построения.','Керек шама мен құралды ата. Бұрышта центр мен шкала нөлін, шеңберде қозғалмайтын центр мен ашылуды тексер. Салған соң градус не қашықтықты тексер.'),why:b('При одинаковом растворе все точки дуги удалены от центра на одну длину. У транспортира шкала отсчитывает поворот от первого луча, поэтому важен именно его ноль.','Бірдей ашылуда доғаның барлық нүктесі центрден бірдей ұзындықта. Транспортир шкаласы бірінші сәуледен бұрылуды санайды, сондықтан сол сәуледегі нөл маңызды.'),use:b('Разметка чертежа и макета. Проверяется порядок действий; качество физического рисунка автоматически не оценивается.','Сызба мен макетті белгілеу. Әрекет реті тексеріледі; нақты сурет сапасы автоматты бағаланбайды.'),error:b('Перепутаны шкалы или циркуль установлен на диаметр вместо радиуса.','Шкалалар шатасқан немесе циркуль радиус орнына диаметрге ашылған.'),
  build:(n,l)=>l===1?num(b(`Угол ${20*n+40}° разделили транспортиром пополам. Какова мера одной части в градусах?`,` ${20*n+40}° бұрыш транспортирмен тең екіге бөлінді. Бір бөлік неше градус?`),10*n+20,[b('Пополам означает две равные меры.','Тең екіге бөлу екі бірдей өлшемді білдіреді.'),b(`${20*n+40}/2=${10*n+20}°.`,`${20*n+40}/2=${10*n+20}°.`)],b('Сначала найди требуемую отметку, потом строй луч.','Алдымен керек белгіні тап, кейін сәулені сал.')):l===2?num(b(`Нужно построить окружность диаметра ${4*n+8}. На какую длину открыть циркуль?`,`Диаметрі ${4*n+8} шеңбер салу керек. Циркульді қандай ұзындыққа ашамыз?`),2*n+4,[b('Раствор равен радиусу, а не диаметру.','Ашылу диаметрге емес, радиусқа тең.'),b(`r=${4*n+8}/2=${2*n+4}.`,`r=${4*n+8}/2=${2*n+4}.`)],b('Диаметр состоит из двух радиусов.','Диаметр екі радиустан тұрады.')):match(b(`Сопоставь этапы 1,2,3 при построении окружности радиуса ${n+2}:O — выбрать центр; r — установить раствор ${n+2}; ○ — провести полный оборот с неподвижной иглой.`,`Радиусы ${n+2} шеңберді салудың 1,2,3 кезеңдерін сәйкестендір:O — центрді таңдау;r — ашылуды ${n+2} етіп орнату;○ — инені қозғалтпай толық айналдыру.`),[{left:'1',right:'O'},{left:'2',right:'r'},{left:'3',right:'○'}],['O','r','○'],[b('Сначала центр, затем требуемое расстояние.','Алдымен центр, кейін керек қашықтық.'),b('После настройки проводим окружность, сохраняя центр и радиус.','Баптаған соң центр мен радиусты сақтап шеңбер жүргіземіз.')],b('Рисование должно быть после настройки инструмента.','Сызу құрал бапталғаннан кейін болуы тиіс.')),
 },
 {
  id:'school-nets',grade:5,pathway:'common',quarter:4,appendix:52,pre:['school-perimeter','units'],title:b('Развёртки куба и коробки','Куб пен қораптың жазбалары'),
  goal:b('Связать плоскую развёртку с шестью гранями тела, найти площадь материала и противоположные грани.','Жазық жазбаны дененің алты жағымен байланыстыру, материал ауданын және қарама-қарсы жақтарды табу.'),
  theory:b('Развёртка получается, когда поверхность коробки разрезают по некоторым рёбрам и раскладывают плоско. У куба шесть одинаковых квадратов, у прямоугольного параллелепипеда три пары равных прямоугольников. Площадь развёртки без клапанов равна полной площади поверхности. Не любой набор шести квадратов складывается в куб: при сгибании грани могут наложиться друг на друга. Для проверки проследи, какая грань станет нижней, какие четыре — стенками и какая — верхней. В используемом крестовом шаблоне четыре квадрата идут в ряд; два оставшихся прикреплены сверху и снизу второго квадрата ряда. Первый и третий в ряду противоположны, второй и четвёртый противоположны; два прикреплённых тоже противоположны. Длина ребра при сгибании не меняется. Площадь измеряется квадратными единицами, объём — кубическими: в задаче на картон нужен именно первый показатель.','Жазба қорап бетін кейбір қыр бойымен кесіп, жазыққа жайғанда шығады. Кубта алты бірдей квадрат, тікбұрышты параллелепипедте үш жұп тең тіктөртбұрыш бар. Қақпақша қосымшаларынсыз жазба ауданы толық бет ауданына тең. Алты квадраттың кез келген орналасуы кубқа жиналмайды: бүктегенде жақтар қабаттасуы мүмкін. Тексеру үшін қай жақ түбі, қай төртеуі қабырғалар, қайсысы үсті болатынын бақыла. Қолданылатын крест үлгісінде төрт квадрат қатар, қалған екеуі қатардың екінші квадратының үсті мен астына жалғанған. Қатардағы бірінші мен үшінші, екінші мен төртінші қарама-қарсы; жалғанған екеуі де қарама-қарсы. Бүктегенде қыр ұзындығы өзгермейді. Аудан квадрат, көлем куб бірлігімен өлшенеді: картон есебіне бірінші көрсеткіш керек.'),
  formula:b('Куб:S=6a². Коробка:S=2(ab+ac+bc). a,b,c>0 — длины рёбер.','Куб:S=6a². Қорап:S=2(ab+ac+bc). a,b,c>0 — қыр ұзындықтары.'),terms:b('Грань — плоская часть поверхности; ребро — сторона грани; противоположные грани не имеют общего ребра.','Жақ — беттің жазық бөлігі; қыр — жақ қабырғасы; қарама-қарсы жақтардың ортақ қыры жоқ.'),method:b('Сосчитай грани, сгруппируй равные. Для площади умножь две длины каждой грани. Для расположения мысленно сгибай по рёбрам и проверяй отсутствие наложений.','Жақтарды санап, теңдерін топта. Аудан үшін әр жақтың екі ұзындығын көбейт. Орналасу үшін қыр бойымен ойша бүктеп, қабаттасуды тексер.'),why:b('Разрезание и поворот граней сохраняют их площади. Поэтому сумма площадей на плоскости равна площади поверхности собранного тела.','Жақтарды кесу және бұру аудандарын сақтайды. Сондықтан жазықтағы аудандар қосындысы жиналған дене бетінің ауданына тең.'),use:b('Картонная упаковка. Модель не включает клеевые клапаны и расход на резку; в реальном проекте их добавляют отдельно.','Картон қаптама. Модель желім қақпақшалары мен кесу шығынын қоспайды; нақты жобада бөлек қосылады.'),error:b('Учтены только видимые грани либо объём выдан вместо площади.','Тек көрінетін жақтар есептелген немесе аудан орнына көлем берілген.'),
  build:(n,l)=>l===1?num(b(`Куб с ребром ${n+1}. Найди площадь его развёртки без клапанов.`,`Қыры ${n+1} куб. Қақпақшасыз жазба ауданын тап.`),6*(n+1)**2,[b(`Один квадрат:(${n+1})²=${(n+1)**2}.`,`Бір квадрат:(${n+1})²=${(n+1)**2}.`),b(`Шесть граней:S=6·${(n+1)**2}=${6*(n+1)**2}.`,`Алты жақ:S=6·${(n+1)**2}=${6*(n+1)**2}.`)],b('Все шесть граней нужны для закрытого куба.','Жабық куб үшін алты жақ та керек.')):l===2?num(b(`Закрытая коробка имеет рёбра ${n+1},${n+2},2. Найди полную площадь развёртки.`,`Жабық қорап қырлары ${n+1},${n+2},2. Жазбаның толық ауданын тап.`),2*((n+1)*(n+2)+2*(n+1)+2*(n+2)),[b('Три пары граней; каждая пара считается дважды.','Жақтардың үш жұбы; әр жұп екі рет есептеледі.'),b(`S=2(${(n+1)*(n+2)}+${2*(n+1)}+${2*(n+2)})=${2*((n+1)*(n+2)+2*(n+1)+2*(n+2))}.`,`S=2(${(n+1)*(n+2)}+${2*(n+1)}+${2*(n+2)})=${2*((n+1)*(n+2)+2*(n+1)+2*(n+2))}.`)],b('У коробки могут быть разные площади граней.','Қорап жақтарының аудандары әртүрлі болуы мүмкін.')):match(b(`Развёртка куба: в ряд ${n}—${n+1}—${n+2}—${n+3}; к квадрату ${n+1} сверху прикреплён ${n+4}, снизу ${n+5}. Сопоставь грани с противоположными после сгибания.`,`Куб жазбасы: қатарда ${n}—${n+1}—${n+2}—${n+3};${n+1} квадратына үстінен ${n+4}, астынан ${n+5} жалғанған. Бүктеген соң жақтарды қарама-қарсы жақтарымен сәйкестендір.`),[{left:String(n),right:String(n+2)},{left:String(n+1),right:String(n+3)},{left:String(n+4),right:String(n+5)}],Array.from({length:6},(_,i)=>String(n+i)),[b('Четыре квадрата ряда образуют пояс; через один становятся противоположными.','Қатардың төрт квадраты белдеу құрайды; біреуін өткізіп тұрғандар қарама-қарсы болады.'),b('Верхняя и нижняя добавленные грани замыкают куб с противоположных сторон.','Үстіңгі және астыңғы қосылған жақтар кубты қарама-қарсы жақтан жабады.')],b('Выбери одну грань основанием и поверни соседние на 90°.','Бір жақты негіз етіп, көршілерін 90°-қа бұр.')),
 },
 {
  id:'school-graphical-systems',grade:7,pathway:'common',quarter:2,appendix:53,pre:['school-coordinate-plane','linear-systems'],title:b('Линейная система на графике','Графиктегі сызықтық жүйе'),
  goal:b('Находить общую точку двух прямых и отличать одно решение, отсутствие решений и совпадение прямых.','Екі түзудің ортақ нүктесін табу, бір шешімді, шешімсіздікті және түзулердің беттесуін ажырату.'),
  theory:b('Каждое линейное уравнение с двумя неизвестными задаёт прямую. Пара (x;y) решает систему, если подходит сразу к обоим уравнениям, поэтому на графике нужна общая точка. Для построения обычной прямой достаточно двух разных точек: выбираем x и вычисляем y. В записи y=kx+b число k задаёт наклон, b — пересечение с вертикальной осью. Разные k дают одно пересечение; одинаковые k и разные b — параллельные прямые без общей точки; одинаковые k и b — одну и ту же прямую с бесконечно многими решениями. Вертикальная прямая x=c не записывается через y=kx+b, её надо строить отдельно. Считывание с рисунка даёт приближение, особенно если пересечение не на целой клетке. Проверяй прочитанные координаты подстановкой, а точный ответ при необходимости найди алгебраически.','Екі белгісізі бар әр сызықтық теңдеу түзу береді. (x;y) жұбы бір мезгілде екі теңдеуге де сәйкес болса жүйе шешімі, сондықтан графикте ортақ нүкте керек. Әдеттегі түзуді салуға екі әртүрлі нүкте жеткілікті:x таңдап,y есептейміз. y=kx+b жазуында k көлбеулікті,b тік осьпен қиылысуды береді. k әртүрлі болса бір қиылысу; бірдей k, әртүрлі b болса ортақ нүктесіз параллель түзулер; бірдей k,b болса шексіз шешімді бір түзу. x=c тік түзуі y=kx+b түрінде жазылмайды, бөлек салынады. Суреттен оқу жуық мән береді, әсіресе қиылысу бүтін торда болмаса. Оқылған координаталарды орнына қойып тексер, қажет болса дәл жауапты алгебрамен тап.'),
  formula:b('y=k₁x+b₁ и y=k₂x+b₂: при k₁≠k₂ x=(b₂−b₁)/(k₁−k₂). Затем найди y.','y=k₁x+b₁ және y=k₂x+b₂:k₁≠k₂ болса x=(b₂−b₁)/(k₁−k₂). Кейін y-ті тап.'),terms:b('Общая точка — принадлежит двум графикам; k — угловой коэффициент; b — вертикальный сдвиг.','Ортақ нүкте — екі графикке тиесілі;k — бұрыштық коэффициент;b — тік жылжу.'),method:b('Запиши обе прямые в удобной форме, отметь по две точки. Найди пересечение и прочитай обе координаты. Подставь их в каждое исходное уравнение.','Екі түзуді ыңғайлы түрде жазып, әрқайсысында екі нүкте белгіле. Қиылысуды тауып, екі координатаны оқы. Оларды әр бастапқы теңдеуге қой.'),why:b('График состоит именно из точек, удовлетворяющих уравнению. Его пересечение с другим графиком выполняет оба условия одновременно.','График дәл теңдеуді қанағаттандыратын нүктелерден тұрады. Басқа графикпен қиылысуы екі шартты бір мезгілде орындайды.'),use:b('Встреча двух тарифов или зависимостей. Текстовая замена графику — таблицы точек и проверка общей пары.','Екі тариф не тәуелділіктің кездесуі. Графиктің мәтіндік баламасы — нүкте кестелері және ортақ жұпты тексеру.'),error:b('Найдена точка только одной прямой либо перепутаны x и y.','Тек бір түзу нүктесі табылған немесе x пен y шатасқан.'),
  build:(n,l)=>l===1?num(b(`Графики x+y=${4*n} и x−y=${2*n}. Найди x координату их пересечения.`,`x+y=${4*n} және x−y=${2*n} графиктері. Қиылысу x координатасын тап.`),3*n,[b(`Сложим равенства:2x=${6*n}.`,`Теңдіктерді қосамыз:2x=${6*n}.`),b(`x=${3*n},y=${n}; пара выполняет оба уравнения.`,`x=${3*n},y=${n}; жұп екі теңдеуді де орындайды.`)],b('Общая точка должна принадлежать обеим прямым.','Ортақ нүкте екі түзуге де тиесілі болуы тиіс.')):l===2?num(b(`Найди y пересечения y=2x+${n} и y=−x+${4*n}.`,`y=2x+${n} және y=−x+${4*n} қиылысуының y мәнін тап.`),3*n,[b(`2x+${n}=−x+${4*n}, значит x=${n}.`,`2x+${n}=−x+${4*n}, демек x=${n}.`),b(`y=2·${n}+${n}=${3*n}; вторая прямая даёт столько же.`,`y=2·${n}+${n}=${3*n}; екінші түзу де осы мәнді береді.`)],b('Сначала получи x; вопрос просит другую координату.','Алдымен x тап; сұрақ басқа координатаны сұрайды.')):choice(b(`Сколько общих точек у y=2x+${n} и y=2x+${n+1}? 0 — ни одной; 1 — одна; ∞ — бесконечно много.`,`y=2x+${n} және y=2x+${n+1} түзулерінде неше ортақ нүкте бар? 0 — жоқ;1 — біреу;∞ — шексіз көп.`),'0',['0','1','∞'],[b('Наклоны одинаковы, вертикальные сдвиги различны.','Көлбеуліктері бірдей, тік жылжулары әртүрлі.'),b('Прямые параллельны и не совпадают:0 пересечений.','Түзулер параллель және беттеспейді:0 қиылысу.')],b('Вычитание уравнений даёт невозможное равенство 0=1.','Теңдеулерді азайту мүмкін емес 0=1 теңдігін береді.')),
 },
 {
  id:'school-polynomial-division',grade:10,pathway:'natural-math',quarter:3,appendix:104,pre:['school-polynomials','factoring'],title:b('Деление многочленов и остаток','Көпмүшелерді бөлу және қалдық'),
  goal:b('Находить частное и остаток, проверять деление обратным умножением и применять теорему об остатке.','Бөлінді мен қалдықты табу, бөлуді кері көбейтумен тексеру және қалдық теоремасын қолдану.'),
  theory:b('Деление многочленов похоже на письменное деление чисел. Делим старший член остатка на старший член делителя, записываем член частного, умножаем на весь делитель и вычитаем. Повторяем, пока степень остатка не станет меньше степени делителя. Отсутствующие степени удобно записать с нулевыми коэффициентами. Результат P(x)=D(x)Q(x)+R(x) проверяется раскрытием скобок. Делитель должен быть ненулевым многочленом. При делении на x−a остаток — постоянное число P(a), потому что при x=a произведение (x−a)Q(x) исчезает. Нулевой остаток означает, что x−a — множитель P. Полиномиальное равенство верно для всех x; если записываем его дробью P/D, отдельно исключаем точки D(x)=0. Не путай частное Q с остатком R и не прекращай вычитание после первого члена.','Көпмүшелерді бөлу сандарды жазбаша бөлуге ұқсайды. Қалдықтың ең жоғары мүшесін бөлгіштің ең жоғары мүшесіне бөліп, бөлінді мүшесін жазамыз, бүкіл бөлгішке көбейтіп азайтамыз. Қалдық дәрежесі бөлгіш дәрежесінен кіші болғанша қайталаймыз. Жоқ дәрежелерді нөл коэффициентпен жазу ыңғайлы. P(x)=D(x)Q(x)+R(x) нәтижесі жақшаларды ашумен тексеріледі. Бөлгіш нөл емес көпмүше болуы тиіс. x−a-ға бөлгенде қалдық тұрақты P(a), өйткені x=a кезінде (x−a)Q(x) көбейтіндісі жоғалады. Нөл қалдық x−a өрнегі P-ның көбейткіші екенін білдіреді. Көпмүшелік теңдік барлық x үшін дұрыс; оны P/D бөлшегімен жазсақ,D(x)=0 нүктелерін бөлек алып тастаймыз. Q бөлінді мен R қалдықты шатастырма, бірінші мүшеден кейін азайтуды тоқтатпа.'),
  formula:b('P=DQ+R, degR<degD; при D=x−a остаток R=P(a). deg — степень многочлена; нулевой остаток допускается.','P=DQ+R,degR<degD;D=x−a болса қалдық R=P(a). deg — көпмүше дәрежесі; нөл қалдық мүмкін.'),terms:b('P — делимое, D — делитель, Q — частное, R — остаток; старший член имеет наибольшую степень.','P — бөлінгіш,D — бөлгіш,Q — бөлінді,R — қалдық; ең жоғары мүшенің дәрежесі ең үлкен.'),method:b('Расположи степени по убыванию. Деление старших членов → умножение всего делителя → вычитание → новый остаток. В конце проверь P=DQ+R.','Дәрежелерді кемімелі ретте қой. Жоғары мүшелерді бөлу → бүкіл бөлгішті көбейту → азайту → жаңа қалдық. Соңында P=DQ+R тексер.'),why:b('Каждый шаг убирает старший член, поэтому степень оставшегося выражения уменьшается. Подстановка корня линейного делителя оставляет только остаток.','Әр қадам ең жоғары мүшені жояды, сондықтан қалған өрнек дәрежесі азаяды. Сызықтық бөлгіш түбірін қою тек қалдықты қалдырады.'),use:b('Разложение многочлена и поиск корней. Проверка на нескольких числах дополняет точное обратное умножение, но не заменяет доказательство произвольного тождества.','Көпмүшені жіктеу және түбір іздеу. Бірнеше санда тексеру дәл кері көбейтуді толықтырады, бірақ кез келген тепе-теңдік дәлелін алмастырмайды.'),error:b('Вычтен только старший член вместо всего произведения с делителем.','Бөлгішпен бүкіл көбейтінді орнына тек ең жоғары мүше азайтылған.'),
  build:(n,l)=>l===1?num(b(`Раздели x²−${n*n} на x−${n}. Найди свободный член частного.`,`x²−${n*n} өрнегін x−${n}-ге бөл. Бөліндінің тұрақты мүшесін тап.`),n,[b(`x²−${n*n}=(x−${n})(x+${n}).`,`x²−${n*n}=(x−${n})(x+${n}).`),b(`Частное x+${n}, остаток 0, свободный член ${n}.`,`Бөлінді x+${n}, қалдық 0, тұрақты мүше ${n}.`)],b('Узнай разность квадратов.','Квадраттар айырымын таны.')):l===2?num(b(`Раздели x²+${n+2}x+${2*n} на x+${n}. Каков свободный член частного?`,`x²+${n+2}x+${2*n} өрнегін x+${n}-ге бөл. Бөліндінің тұрақты мүшесі неше?`),2,[b(`Первый член x; вычитание x(x+${n}) оставляет 2x+${2*n}.`,`Бірінші мүше x;x(x+${n}) азайтқанда 2x+${2*n} қалады.`),b(`Остаток после 2(x+${n}) равен 0; частное x+2.`,`2(x+${n}) кейін қалдық 0; бөлінді x+2.`)],b('После первого вычитания раздели оставшийся старший член.','Бірінші азайтудан кейін қалған ең жоғары мүшені бөл.')):num(b(`Найди остаток при делении P(x)=x²+${n}x+1 на x−${n+1}.`,`P(x)=x²+${n}x+1 өрнегін x−${n+1}-ге бөлгендегі қалдықты тап.`),2*n*n+3*n+2,[b(`По теореме об остатке R=P(${n+1}).`,`Қалдық теоремасы бойынша R=P(${n+1}).`),b(`R=(${n+1})²+${n}·${n+1}+1=${2*n*n+3*n+2}.`,`R=(${n+1})²+${n}·${n+1}+1=${2*n*n+3*n+2}.`)],b('Подставь корень делителя, следи за знаком.','Бөлгіш түбірін қой, таңбаны бақыла.')),
 },
 {
  id:'school-histograms',grade:8,pathway:'common',quarter:3,appendix:53,pre:['school-frequency-tables','school-decimals'],title:b('Интервальные ряды и гистограмма','Интервалдық қатарлар және гистограмма'),
  goal:b('Группировать данные по интервалам, читать частоты и учитывать ширину столбцов.','Деректерді интервалдарға топтау, жиіліктерді оқу және баған енін ескеру.'),
  theory:b('Когда разных значений много, их объединяют в интервалы. Границы должны распределять каждое наблюдение ровно в один интервал: например,[0;2) включает 0, но не 2, а следующий [2;6) включает 2. В последнем интервале можно включить правую границу, если это явно указано. Частоты всех интервалов складываются в объём данных N. Гистограмма отличается от диаграммы категорий: интервалы стоят на числовой оси, соседние столбцы примыкают. При равных ширинах можно показывать частоту высотой; при разных ширинах в модели плотности высота равна частоте, делённой на ширину. Тогда площадь каждого прямоугольника, а не высота, показывает частоту. Поэтому широкий низкий столбец иногда содержит больше наблюдений, чем узкий высокий. Средние значения, восстановленные по серединам интервалов, обычно приблизительны: точные отдельные данные уже не видны.','Әртүрлі мән көп болса, олар интервалдарға біріктіріледі. Шекаралар әр бақылауды дәл бір интервалға бөлуі тиіс: мысалы,[0;2) нөлді қамтиды, бірақ 2-ні емес; келесі [2;6) 2-ні қамтиды. Соңғы интервалда оң шекараны қосуға болады, егер анық көрсетілсе. Барлық интервал жиіліктері N деректер көлеміне қосылады. Гистограмма санат диаграммасынан өзгеше: интервалдар сан осінде, көрші бағандар жанасады. Ендері бірдей болса биіктікпен жиілік көрсетіледі; ендері әртүрлі тығыздық моделінде биіктік жиіліктің енге бөліндісі. Онда биіктік емес, әр тіктөртбұрыш ауданы жиілікті көрсетеді. Сондықтан кең аласа баған кейде тар биік бағаннан көбірек бақылау қамтиды. Интервал орталарынан қалпына келген орта мән әдетте жуық: нақты жеке деректер көрінбейді.'),
  formula:b('N=Σnᵢ; плотность hᵢ=nᵢ/wᵢ, wᵢ>0; площадь wᵢhᵢ=nᵢ. nᵢ — частота,i — номер интервала,wᵢ — ширина.','N=Σnᵢ; тығыздық hᵢ=nᵢ/wᵢ,wᵢ>0; аудан wᵢhᵢ=nᵢ. nᵢ — жиілік,i — интервал нөмірі,wᵢ — ені.'),terms:b('Интервальный ряд — таблица диапазонов и частот; плотность частоты — число наблюдений на единицу ширины.','Интервалдық қатар — аралықтар мен жиіліктер кестесі; жиілік тығыздығы — ен бірлігіне бақылау саны.'),method:b('Прочитай включение границ. Сложи частоты. Для неравных ширин вычисли высоты через n/w и проверяй частоту площадью.','Шекараның қамтылуын оқы. Жиіліктерді қос. Ендер әртүрлі болса биіктікті n/w арқылы есептеп, жиілікті ауданмен тексер.'),why:b('Чтобы площадь сохраняла количество наблюдений, увеличение ширины должно уменьшать высоту в том же отношении. Это предотвращает искажение при сравнении интервалов.','Аудан бақылаулар санын сақтау үшін ен артса биіктік сол қатынаста азаюы тиіс. Бұл интервалдарды салыстырғанда бұрмалауды болдырмайды.'),use:b('Распределение времени поездок. Текстовая замена визуалу: для каждого интервала указаны левая/правая границы, частота и высота. Модель разных ширин объясняется явно.','Сапар уақытының таралуы. Көрнекінің мәтіндік баламасы: әр интервалдың сол/оң шекарасы, жиілігі және биіктігі берілген. Әртүрлі ен моделі анық түсіндіріледі.'),error:b('На неравных интервалах высота принята за число наблюдений.','Ендері әртүрлі интервалда биіктік бақылаулар саны деп алынған.'),
  build:(n,l)=>{const table=b(`Интервалы [0;2),[2;6),[6;10] имеют частоты ${2*n},${4*n},${8*n}.`,`[0;2),[2;6),[6;10] интервалдары жиіліктері ${2*n},${4*n},${8*n}.`);return l===1?num(b(`${table.ru} Найди объём N.`,`${table.kk} N көлемін тап.`),14*n,[b('Наблюдения распределены по трём непересекающимся интервалам.','Бақылаулар қиылыспайтын үш интервалға бөлінген.'),b(`N=${2*n}+${4*n}+${8*n}=${14*n}.`,`N=${2*n}+${4*n}+${8*n}=${14*n}.`)],b('Сложи частоты, не границы интервалов.','Интервал шекарасын емес, жиіліктерді қос.')):l===2?num(b(`${table.ru} Найди долю третьего интервала.`,`${table.kk} Үшінші интервал үлесін тап.`),4/7,[b(`Часть ${8*n}, всего ${14*n}.`,`Бөлік ${8*n}, барлығы ${14*n}.`),b(`Доля ${8*n}/${14*n}=4/7.`,`Үлес ${8*n}/${14*n}=4/7.`)],b('Доля вычисляется по частотам, не по ширине.','Үлес ендермен емес, жиіліктермен есептеледі.')):match(b(`${table.ru} Сопоставь интервалы с высотами гистограммы плотности, у которой площадь столбца равна частоте.`,`${table.kk} Баған ауданы жиілікке тең тығыздық гистограммасының биіктіктерімен интервалдарды сәйкестендір.`),[{left:'[0;2)',right:String(n)},{left:'[2;6)',right:String(n)},{left:'[6;10]',right:String(2*n)}],[String(n),String(2*n),String(4*n)],[b('Ширины 2,4,4; делим соответствующие частоты на них.','Ендер 2,4,4; сәйкес жиілікті соларға бөлеміз.'),b(`Высоты ${2*n}/2=${n},${4*n}/4=${n},${8*n}/4=${2*n}.`,`Биіктіктер ${2*n}/2=${n},${4*n}/4=${n},${8*n}/4=${2*n}.`)],b('Одинаковые высоты не означают одинаковые частоты при разных ширинах.','Ендер әртүрлі болса бірдей биіктік бірдей жиілікті білдірмейді.'));},
 },
 {
  id:'school-right-triangle-trig',grade:8,pathway:'common',quarter:1,appendix:54,pre:['triangles','fractions'],title:b('Тригонометрия прямоугольного треугольника','Тікбұрышты үшбұрыш тригонометриясы'),
  goal:b('По отношению к выбранному острому углу правильно назвать стороны и вычислить sin,cos,tan.','Таңдалған сүйір бұрышқа қатысты қабырғаларды дұрыс атап,sin,cos,tan есептеу.'),
  theory:b('В прямоугольном треугольнике гипотенуза лежит напротив угла 90° и является самой длинной стороной. Два других отрезка — катеты. Для выбранного острого угла один катет напротив него, другой прилегает к нему. Синус — противолежащий катет, делённый на гипотенузу; косинус — прилежащий катет, делённый на гипотенузу; тангенс — противолежащий, делённый на прилежащий; котангенс — обратное отношение, прилежащий, делённый на противолежащий. При выборе второго острого угла катеты меняются ролями, а гипотенуза остаётся той же. Все эти отношения без единиц: при увеличении всего треугольника в одинаковое число раз они не меняются. Для острого угла sin и cos находятся между 0 и 1, а tan положителен. Не подставляй отношения в произвольный непрямоугольный треугольник: там понадобятся теоремы синусов и косинусов.','Тікбұрышты үшбұрышта гипотенуза 90° бұрышқа қарсы жатады және ең ұзын қабырға. Қалған екеуі — катеттер. Таңдалған сүйір бұрыш үшін бір катет қарсы, екіншісі іргелес. Синус — қарсы катеттің гипотенузаға қатынасы; косинус — іргелес катеттің гипотенузаға қатынасы; тангенс — қарсы катеттің іргелес катетке қатынасы; котангенс — кері қатынас, іргелес катеттің қарсы катетке қатынасы. Екінші сүйір бұрыш таңдалса катеттер рөлін ауыстырады, гипотенуза сол қалады. Бұл қатынастар өлшемсіз: бүкіл үшбұрышты бірдей есе үлкейтсе өзгермейді. Сүйір бұрыштың sin,cos мәндері 0 мен 1 арасында,tan оң. Қатынастарды кез келген тікбұрышты емес үшбұрышқа қолданба: онда синустар мен косинустар теоремалары керек.'),
  formula:b('sinα=a/c;cosα=b/c;tanα=a/b;cotα=b/a;a²+b²=c². a — противолежащий,b — прилежащий катет,c — гипотенуза,0<α<90°.','sinα=a/c;cosα=b/c;tanα=a/b;cotα=b/a;a²+b²=c². a — қарсы,b — іргелес катет,c — гипотенуза,0<α<90°.'),terms:b('Противолежащий катет не касается вершины выбранного угла; прилежащий касается; отношение сравнивает длины делением.','Қарсы катет таңдалған бұрыш төбесіне тимейді; іргелесі тиеді; қатынас ұзындықтарды бөлумен салыстырады.'),method:b('Отметь прямой и выбранный острый углы. Подпиши три стороны. Выбери отношение и сократи единицы. Проверь диапазон ответа.','Тік және таңдалған сүйір бұрышты белгіле. Үш қабырғаны ата. Қатынасты таңдап, бірліктерді қысқарт. Жауап аралығын тексер.'),why:b('Подобные прямоугольные треугольники с одинаковым острым углом имеют одинаковые отношения соответствующих сторон. Поэтому отношение зависит от угла, а не размера.','Бірдей сүйір бұрышы бар ұқсас тікбұрышты үшбұрыштардың сәйкес қабырғалар қатынасы бірдей. Сондықтан қатынас өлшемге емес, бұрышқа тәуелді.'),use:b('Уклон рампы и высота по расстоянию. Текстовый чертёж: прямой угол C, гипотенуза AB, для угла A противолежит BC.','Пандус көлбеуі және қашықтықтан биіктік. Мәтіндік сызба: тік бұрыш C, гипотенуза AB,A бұрышына қарсы BC.'),error:b('Катеты названы без выбранного угла или катет принят за гипотенузу.','Катеттер таңдалған бұрышсыз аталған немесе катет гипотенуза деп алынған.'),
  build:(n,l)=>{const data=b(`∠C=90°,BC=${3*n},AC=${4*n},AB=${5*n}.`,`∠C=90°,BC=${3*n},AC=${4*n},AB=${5*n}.`);return l===1?num(b(`${data.ru} Найди sin A.`,`${data.kk} sin A-ны тап.`),3/5,[b('Для A противолежит BC, гипотенуза AB.','A-ға қарсы BC, гипотенуза AB.'),b(`sin A=${3*n}/${5*n}=3/5=0,6.`,`sin A=${3*n}/${5*n}=3/5=0,6.`)],b('Синус использует сторону напротив выбранного угла.','Синус таңдалған бұрышқа қарсы қабырғаны қолданады.')):l===2?num(b(`${data.ru} Найди cos A.`,`${data.kk} cos A-ны тап.`),4/5,[b('Для A прилежащий катет AC.','A-ға іргелес катет AC.'),b(`cos A=${4*n}/${5*n}=4/5=0,8.`,`cos A=${4*n}/${5*n}=4/5=0,8.`)],b('Из двух касающихся A сторон выбери катет, не гипотенузу.','A-ға тиетін екі қабырғадан гипотенузаны емес, катетті таңда.')):match(b(`${data.ru} Сопоставь отношения для A.`,`${data.kk} A үшін қатынастарды сәйкестендір.`),[{left:'sin A',right:'3/5'},{left:'cos A',right:'4/5'},{left:'tan A',right:'3/4'},{left:'cot A',right:'4/3'}],['3/5','4/5','3/4','4/3'],[b('sin и cos имеют общий знаменатель AB.','sin мен cos ортақ AB бөлімін алады.'),b('tan сравнивает катеты:BC/AC=3/4;cot берёт обратное отношение 4/3. Сокращение одинакового множителя сохраняет отношение.','tan катеттерді салыстырады:BC/AC=3/4;cot кері 4/3 қатынасын алады. Бірдей көбейткішті қысқарту қатынасты сақтайды.')],b('Подпиши стороны для A ещё раз, не по положению картинки.','A үшін қабырғаларды сурет орнына емес, қайта ата.'));},
 },
 {
  id:'school-plane-equations',grade:8,pathway:'common',quarter:4,appendix:54,pre:['school-coordinate-plane','functions','school-polynomials'],title:b('Уравнения прямой и окружности','Түзу мен шеңбер теңдеулері'),
  goal:b('Читать центр и радиус окружности, составлять прямую по двум точкам и проверять принадлежность точки.','Шеңбер центрі мен радиусын оқу, екі нүкте арқылы түзуді құру және нүкте тиесілігін тексеру.'),
  theory:b('Уравнение фигуры описывает все её точки: подставив координаты, получаем верное равенство именно для точек фигуры. Прямая y=kx+b имеет постоянный наклон k. По двум точкам с разными x находим k=(y₂−y₁)/(x₂−x₁), потом b. Если x₁=x₂, прямая вертикальна и записывается x=x₁, делить на ноль нельзя. Окружность — точки на одинаковом расстоянии r от центра (a;b). По Пифагору её уравнение (x−a)²+(y−b)²=r². Знак в скобке обратный знаку координаты центра; справа квадрат радиуса, а не сам радиус. Точки внутри дают сумму меньше r², снаружи больше. Для проверки центра в уравнение подставляется ноль слева, поэтому при r>0 сам центр не принадлежит окружности. Круг включает внутренние точки, окружность только границу.','Фигура теңдеуі оның барлық нүктесін сипаттайды: координаталарды қойғанда дұрыс теңдік дәл фигура нүктелерінде шығады. y=kx+b түзуінің k көлбеулігі тұрақты. x-тері әртүрлі екі нүктеден k=(y₂−y₁)/(x₂−x₁), кейін b табамыз. x₁=x₂ болса түзу тік және x=x₁ деп жазылады, нөлге бөлуге болмайды. Шеңбер — (a;b) центрінен бірдей r қашықтықтағы нүктелер. Пифагор бойынша теңдеуі (x−a)²+(y−b)²=r². Жақшадағы таңба центр координатасы таңбасына кері; оң жақта радиустың өзі емес, квадраты. Ішкі нүктелер қосындысы r²-тан кіші, сыртқысы үлкен. Центрді қойғанда сол жақ нөл, сондықтан r>0 кезінде центр шеңберге жатпайды. Дөңгелек ішкі нүктелерді қамтиды, шеңбер тек шекара.'),
  formula:b('k=Δy/Δx,Δx≠0;b=y₁−kx₁. Окружность:(x−a)²+(y−b)²=r²,r>0.','k=Δy/Δx,Δx≠0;b=y₁−kx₁. Шеңбер:(x−a)²+(y−b)²=r²,r>0.'),terms:b('Δ — изменение между точками; центр (a;b); r — радиус; принадлежность — точка удовлетворяет уравнению.','Δ — нүктелер арасындағы өзгеріс; центр (a;b);r — радиус; тиесілік — нүкте теңдеуді орындайды.'),method:b('Определи вид фигуры. Для прямой проверь Δx; для окружности выдели центр и r². Подставляй точку полностью, обе координаты.','Фигура түрін анықта. Түзуде Δx-ті, шеңберде центр мен r²-ты анықта. Нүктенің екі координатасын да толық қой.'),why:b('Уравнение окружности — квадрат расстояния до центра. Поэтому оно одинаково проверяет точки в любом направлении от центра.','Шеңбер теңдеуі — центрге қашықтық квадраты. Сондықтан центрден кез келген бағыттағы нүктені бірдей тексереді.'),use:b('Область покрытия датчика и координатный чертёж. Текстовая замена — центр, радиус и список точек.','Сенсор қамту аймағы және координаталық сызба. Мәтіндік баламасы — центр, радиус және нүкте тізімі.'),error:b('Взято число справа без квадратного корня или знак центра перепутан.','Оң жақ сан квадрат түбірсіз алынған немесе центр таңбасы шатасқан.'),
  build:(n,l)=>l===1?num(b(`Найди радиус (x−${n})²+(y−${n+1})²=${(n+2)**2}.`,`(x−${n})²+(y−${n+1})²=${(n+2)**2} радиусын тап.`),n+2,[b('Справа r², радиус положительный.','Оң жақ r², радиус оң.'),b(`r=√${(n+2)**2}=${n+2}.`,`r=√${(n+2)**2}=${n+2}.`)],b('Не перепутай r с r².','r мен r²-ты шатастырма.')):l===2?num(b(`Прямая проходит через (${n};${2*n}) и (${n+2};${2*n+6}). Найди k в y=kx+b.`,`Түзу (${n};${2*n}) және (${n+2};${2*n+6}) арқылы өтеді. y=kx+b ішіндегі k-ны тап.`),3,[b(`Δx=2,Δy=6.`,`Δx=2,Δy=6.`),b('k=6/2=3; ненулевое Δx разрешает формулу.','k=6/2=3; нөл емес Δx формуланы қолдануға мүмкіндік береді.')],b('Наклон — вертикальное изменение на горизонтальное.','Көлбеулік — тік өзгерістің көлденеңге қатынасы.')):many(b(`Центр O(${n};${n+1}), радиус ${n+2}. Какие точки на окружности? A(${2*n+2};${n+1}),B(−2;${n+1}),C(${2*n+2};${2*n+3}),D(${n};${n+1}).`,`O(${n};${n+1}) центр, радиус ${n+2}. Қай нүктелер шеңберде? A(${2*n+2};${n+1}),B(−2;${n+1}),C(${2*n+2};${2*n+3}),D(${n};${n+1}).`),['A','B'],['A','B','C','D'],[b(`A и B отстоят от O по горизонтали на ${n+2}.`,`A мен B O-дан көлденең ${n+2} қашықтықта.`),b(`У C квадрат расстояния 2·${(n+2)**2};D — центр, расстояние 0. Только A,B дают r².`,`C қашықтық квадраты 2·${(n+2)**2};D — центр, қашықтық 0. Тек A,B r² береді.`)],b('Сравни сумму квадратов смещений с r² для каждой точки.','Әр нүктеде орын ауыстыру квадраттарының қосындысын r²-пен салыстыр.')),
 },
 {
  id:'school-two-variable-regions',grade:9,pathway:'common',quarter:1,appendix:53,pre:['school-plane-equations','linear-inequalities'],title:b('Области неравенств двух переменных','Екі айнымалы теңсіздіктер аймақтары'),
  goal:b('Выбирать нужную сторону границы и находить пересечение областей с учётом включённых точек.','Шекараның керек жағын таңдау және қамтылған нүктелерді ескеріп аймақтардың қиылысуын табу.'),
  theory:b('Решение неравенства с x и y — множество точек, а не один интервал на прямой. Сначала заменяем знак неравенства равенством и получаем границу. У x+y≤c это прямая, у x²+y²≤r² — окружность с внутренностью. Знаки ≤ и ≥ включают границу: рисуем сплошной линией. Знаки < и > исключают: используем пунктир. Для выбора стороны подставь удобную точку, не лежащую на границе, часто (0;0). Если условие верно, выбирается её сторона, если нет — противоположная. В системе надо выполнить все условия, поэтому берём общую часть областей. Чтение «целые координаты» дополнительно ограничивает ответ узлами решётки; все точки области бесконечны, даже когда целых пар мало. Для круговых границ проверка расстояния отличает внутренность от внешности.','x,y бар теңсіздік шешімі түзудегі бір интервал емес, нүктелер жиыны. Алдымен теңсіздік таңбасын теңдікпен ауыстырып, шекара аламыз. x+y≤c үшін түзу,x²+y²≤r² үшін ішімен бірге шеңбер. ≤,≥ таңбалары шекараны қамтиды: тұтас сызықпен саламыз. <,> қамтымайды: үзік сызық қолданамыз. Жақты таңдау үшін шекарада жатпайтын ыңғайлы нүктені, жиі (0;0)-ді қой. Шарт дұрыс болса оның жағы, болмаса қарсы жағы таңдалады. Жүйеде барлық шарт орындалуы тиіс, сондықтан аймақтардың ортақ бөлігін аламыз. «Бүтін координаталар» талабы жауапты тор түйіндерімен шектейді; бүтін жұптар аз болса да аймақтың барлық нүктесі шексіз. Дөңгелек шекарада қашықтықты тексеру ішін сыртынан ажыратады.'),
  formula:b('x+y≤c — полуплоскость с границей;x²+y²≤r² — круг r≥0; система означает пересечение.','x+y≤c — шекарасы бар жартыжазықтық;x²+y²≤r² — r≥0 дөңгелек; жүйе қиылысуды білдіреді.'),terms:b('Граница разделяет области; решётка — точки с целыми координатами; пересечение выполняет каждое условие.','Шекара аймақтарды бөледі; тор — бүтін координаталы нүктелер; қиылысу әр шартты орындайды.'),method:b('Построй границу и выбери её включение. Проверь тестовую точку. Для системы закрась только общую часть; для целых пар считай точки построчно.','Шекараны салып, қамтылуын таңда. Сынақ нүктесін тексер. Жүйеде тек ортақ бөлікті боя; бүтін жұптарды жолмен сана.'),why:b('Каждая точка проверяется подстановкой. График объединяет все успешные проверки в одну видимую область; пересечение соответствует слову «и».','Әр нүкте орнына қоюмен тексеріледі. График барлық сәтті тексеруді көрінетін бір аймаққа біріктіреді; қиылысу «және» сөзіне сәйкес.'),use:b('Допустимые сочетания двух ресурсов. Текстовая замена визуалу — условия и проверка списка координат.','Екі ресурстың мүмкін үйлесімі. Көрнекінің мәтіндік баламасы — шарттар мен координата тізімін тексеру.'),error:b('Объединены области системы или исключена граница при ≤.','Жүйе аймақтары біріктірілген немесе ≤ кезінде шекара алынған.'),
  build:(n,l)=>l===1?choice(b(`Для x+y≤${2*n+1} точка (${n};${n+1}):A — принадлежит границе и решению;B — границе, но не решению;C — только внутренности.`,`x+y≤${2*n+1} үшін (${n};${n+1}) нүктесі:A — шекара мен шешімге тиесілі;B — шекараға, бірақ шешімге емес;C — тек ішкі аймаққа.`),'A',['A','B','C'],[b(`Сумма координат ${2*n+1}, равна правой части.`,`Координата қосындысы ${2*n+1}, оң жаққа тең.`),b('Знак ≤ включает равенство: граница входит в решение.','≤ таңбасы теңдікті қамтиды: шекара шешімге кіреді.')],b('Отдельно проверь равенство и тип знака.','Теңдікті және таңба түрін бөлек тексер.')):l===2?num(b(`Сколько целых пар (x;y) удовлетворяет x≥0,y≥0,x+y≤${n}?`,`x≥0,y≥0,x+y≤${n} шартын неше бүтін (x;y) жұбы орындайды?`),(n+1)*(n+2)/2,[b(`При x=0 есть ${n+1} значений y; при x=1 — ${n}, и так до 1.`,`x=0 кезінде y-тің ${n+1} мәні;x=1 кезінде ${n}, осылай 1-ге дейін.`),b(`Сумма 1+…+${n+1}=(${n+1}·${n+2})/2=${(n+1)*(n+2)/2}.`,`Қосынды 1+…+${n+1}=(${n+1}·${n+2})/2=${(n+1)*(n+2)/2}.`)],b('Не забудь точки на осях и границе.','Осьтер мен шекарадағы нүктелерді ұмытпа.')):many(b(`Выбери точки, выполняющие x²+y²≤${n*n},y≥0:A(${n};0),B(0;${n}),C(0;−${n}),D(${n};${n}).`,`x²+y²≤${n*n},y≥0 орындайтын нүктелерді таңда:A(${n};0),B(0;${n}),C(0;−${n}),D(${n};${n}).`),['A','B'],['A','B','C','D'],[b('A и B на окружности и в верхней полуплоскости.','A мен B шеңберде және жоғарғы жартыжазықтықта.'),b(`C нарушает y≥0;D даёт сумму квадратов ${2*n*n}>${n*n}.`,`C y≥0-ді бұзады;D квадраттар қосындысы ${2*n*n}>${n*n} береді.`)],b('Каждая выбранная точка должна пройти оба условия.','Әр таңдалған нүкте екі шарттан да өтуі тиіс.')),
 },
 {
  id:'school-recurrence-induction',grade:9,pathway:'common',quarter:2,appendix:53,pre:['arithmetic','geometric'],title:b('Рекурсия и математическая индукция','Рекурсия және математикалық индукция'),
  goal:b('Вычислять члены по предыдущим и различать проверку примеров с доказательством для всех натуральных индексов.','Алдыңғы мүшелерден келесісін есептеу, мысал тексеру мен барлық натурал индекс үшін дәлелдеуді ажырату.'),
  theory:b('Рекуррентное правило задаёт следующий член через предыдущий; без начального значения оно обычно не определяет единственную последовательность. Например,a₁=3,aₖ₊₁=aₖ+2 строит 3,5,7,… . Прямая формула сразу даёт член по его номеру, но её ещё нужно обосновать. Проверка нескольких членов не доказывает утверждение для всех. Математическая индукция состоит из базы и перехода. База проверяет первый допустимый индекс. В переходе предполагаем утверждение для произвольного k и из этого выводим его для k+1. Тогда от базы последовательно получаем каждый следующий индекс. Предположение не является готовым выводом для k+1; именно его необходимо доказать. Например, если сумма первых k нечётных чисел равна k², добавление следующего 2k+1 даёт k²+2k+1=(k+1)². Индекс — номер члена, а не значение этого члена.','Рекурренттік ереже келесі мүшені алдыңғысынан береді; бастапқы мәнсіз әдетте жалғыз тізбек анықталмайды. Мысалы,a₁=3,aₖ₊₁=aₖ+2 ережесі 3,5,7,… құрады. Тікелей формула мүшені нөмірінен бірден береді, бірақ оны негіздеу керек. Бірнеше мүшені тексеру барлық индекс үшін дәлел емес. Математикалық индукция база мен өтуден тұрады. База бірінші мүмкін индексті тексереді. Өтуде тұжырымды кез келген k үшін жорамалдап, одан k+1 үшін шығарамыз. Осылай базадан әр келесі индекске кезекпен жетеміз. Жорамал k+1 үшін дайын қорытынды емес; дәл соны дәлелдеу қажет. Мысалы, алғашқы k тақ сан қосындысы k² болса, келесі 2k+1-ді қосу k²+2k+1=(k+1)² береді. Индекс — мүше нөмірі, оның мәні емес.'),
  formula:b('aₖ₊₁=aₖ+d; bₖ₊₁=qbₖ. Индукция:P(1) и [P(k)⇒P(k+1)] дают P(m) для всех m≥1.','aₖ₊₁=aₖ+d;bₖ₊₁=qbₖ. Индукция:P(1) және [P(k)⇒P(k+1)] барлық m≥1 үшін P(m) береді.'),terms:b('d — прибавка,q — множитель;P(k) — утверждение об индексе k; база и переход — обязательные части доказательства.','d — қосылатын шама,q — көбейткіш;P(k) — k индексі туралы тұжырым; база мен өту — дәлелдеудің міндетті бөліктері.'),method:b('Для вычисления выпиши первый член и делай ровно нужное число переходов. Для доказательства назови базу, гипотезу, переход и общий вывод.','Есептеу үшін бірінші мүшені жазып, дәл керек өтулер санын орында. Дәлелдеуде база, жорамал, өту және жалпы қорытындыны ата.'),why:b('Индукция похожа на цепь: база запускает первое звено, переход соединяет каждое звено со следующим. Отдельные примеры не гарантируют связь всей цепи.','Индукция тізбекке ұқсайды: база бірінші буынды бастайды, өту әр буынды келесімен қосады. Жеке мысалдар бүкіл тізбек байланысын қамтамасыз етпейді.'),use:b('Закономерности последовательностей. Автоматически оценивается порядок логических этапов и вычисления; свободное доказательство требует проверки человеком.','Тізбек заңдылықтары. Логикалық кезең реті мен есептеу автоматты бағаланады; еркін дәлелдеуді адам тексеруі қажет.'),error:b('Сделан лишний переход или частный пример объявлен доказательством.','Артық өту жасалған немесе жеке мысал дәлел деп алынған.'),
  build:(n,l)=>l===1?num(b(`a₁=${n},aₖ₊₁=aₖ+2. Найди a₄.`,`a₁=${n},aₖ₊₁=aₖ+2. a₄-ті тап.`),n+6,[b(`a₂=${n+2},a₃=${n+4}.`,`a₂=${n+2},a₃=${n+4}.`),b(`a₄=${n+4}+2=${n+6}; от первого члена три перехода.`,`a₄=${n+4}+2=${n+6}; біріншіден үш өту.`)],b('Начальный член уже имеет номер 1.','Бастапқы мүшенің нөмірі 1 болып тұр.')):l===2?num(b(`b₁=${n},bₖ₊₁=2bₖ. Найди b₄.`,`b₁=${n},bₖ₊₁=2bₖ. b₄-ті тап.`),8*n,[b(`b₂=${2*n},b₃=${4*n}.`,`b₂=${2*n},b₃=${4*n}.`),b(`b₄=${8*n}; три умножения на 2.`,`b₄=${8*n};2-ге үш көбейту.`)],b('Прибавка и множитель — разные правила.','Қосу мен көбейткіш — әртүрлі ереже.')):match(b(`Упорядочь доказательство 1+3+…+(2m−1)=m²: B — проверить m=1;H — предположить сумму k²;S — добавить 2k+1 и получить (k+1)²;C — сделать вывод для всех m≥1. Контроль перехода при k=${n}:${n*n}+${2*n+1}=${(n+1)**2}.`,`1+3+…+(2m−1)=m² дәлелін ретте:B — m=1 тексеру;H — қосынды k² деп жорамалдау;S — 2k+1 қосып,(k+1)² алу;C — барлық m≥1 үшін қорытынды жасау. k=${n} өтуді бақылау:${n*n}+${2*n+1}=${(n+1)**2}.`),[{left:'1',right:'B'},{left:'2',right:'H'},{left:'3',right:'S'},{left:'4',right:'C'}],['B','H','S','C'],[b('Сначала база; затем гипотеза для произвольного k.','Алдымен база; кейін кез келген k үшін жорамал.'),b('Из гипотезы доказывается переход, и только вместе с базой следует общий вывод.','Жорамалдан өту дәлелденеді, тек базамен бірге жалпы қорытынды шығады.')],b('Вывод должен быть после доказанного перехода.','Қорытынды дәлелденген өтуден кейін болуы тиіс.')),
 },
 {
  id:'school-sine-cosine-laws',grade:9,pathway:'common',quarter:3,appendix:54,pre:['school-right-triangle-trig','radicals'],title:b('Теоремы синусов и косинусов','Синустар және косинустар теоремалары'),
  goal:b('Связывать стороны с противоположными углами и выбирать теорему по данным треугольника.','Қабырғаларды қарсы бұрыштармен байланыстыру және үшбұрыш деректері бойынша теорема таңдау.'),
  theory:b('В произвольном треугольнике обозначаем сторону a напротив угла A,b напротив B,c напротив C. Теорема синусов сравнивает каждую сторону с синусом именно противоположного угла. Она удобна, когда известна такая пара и ещё угол или сторона. Теорема косинусов связывает две стороны и угол между ними с третьей стороной. При 90° косинус нулевой, и формула становится теоремой Пифагора. Если известны три стороны, из формулы можно найти косинус нужного угла. Сумма углов 180°, а все стороны положительны и должны выполнять неравенство треугольника. При данных «две стороны и угол напротив одной» синус иногда допускает два угла A и 180°−A: одного ответа калькулятора может быть недостаточно. В этой подборке условия выбираются без такой неоднозначности. Всегда проверяй, что противоположная сторона и угол относятся к одной паре.','Кез келген үшбұрышта a қабырғасын A бұрышына,b-ны B-ға,c-ны C-ға қарсы белгілейміз. Синустар теоремасы әр қабырғаны дәл қарсы бұрыш синусымен салыстырады. Осындай жұп және тағы бұрыш не қабырға белгілі болса ыңғайлы. Косинустар теоремасы екі қабырға мен олардың арасындағы бұрышты үшінші қабырғамен байланыстырады. 90° кезінде косинус нөл, формула Пифагор теоремасына айналады. Үш қабырға белгілі болса формуладан керек бұрыш косинусын табуға болады. Бұрыш қосындысы 180°, барлық қабырғалар оң және үшбұрыш теңсіздігін орындауы тиіс. «Екі қабырға және біреуіне қарсы бұрыш» дерегінде синус кейде A және 180°−A екі бұрыш береді: калькулятордың жалғыз жауабы жеткіліксіз болуы мүмкін. Бұл жинақ шарттары осындай екіұштылықсыз таңдалған. Қарсы қабырға мен бұрыштың бір жұпқа жататынын әрдайым тексер.'),
  formula:b('a/sin A=b/sin B=c/sin C=2R; c²=a²+b²−2ab cos C. R — радиус описанной окружности,C — угол между a и b.','a/sin A=b/sin B=c/sin C=2R;c²=a²+b²−2ab cos C. R — сырттай сызылған шеңбер радиусы,C — a мен b арасындағы бұрыш.'),terms:b('Противоположный угол не касается стороны; включённый угол образован двумя указанными сторонами.','Қарсы бұрыш қабырғаға тимейді; аралық бұрыш аталған екі қабырғадан құралады.'),method:b('Сделай пары сторона–угол. Для двух сторон и включённого угла выбирай косинусы; для известной противоположной пары — синусы. Проверь сумму углов и длины.','Қабырға–бұрыш жұптарын жаса. Екі қабырға мен аралық бұрышқа косинустарды; белгілі қарсы жұпқа синустарды таңда. Бұрыш қосындысы мен ұзындықтарды тексер.'),why:b('Теорема косинусов учитывает, насколько две стороны направлены одинаково; при прямом угле поправка исчезает. Теорема синусов даёт общее отношение через один радиус.','Косинустар теоремасы екі қабырғаның бағыттасуын ескереді; тік бұрышта түзету жоғалады. Синустар теоремасы бір радиус арқылы ортақ қатынас береді.'),use:b('Расстояние между двумя пунктами, когда измеримы два луча и угол между ними. Все углы в этих числовых задачах даны в градусах.','Екі сәуле мен олардың арасындағы бұрыш өлшенсе, екі орын арасындағы қашықтық. Бұл сандық есептердің барлық бұрышы градуспен берілген.'),error:b('В формуле синусов взят соседний угол или в косинусах перепутан включённый угол.','Синустар формуласында көрші бұрыш алынған немесе косинустарда аралық бұрыш шатасқан.'),
  build:(n,l)=>l===1?num(b(`Стороны ${3*n} и ${4*n} образуют 90°. Найди третью сторону.`,` ${3*n} және ${4*n} қабырғалары 90° құрайды. Үшінші қабырғаны тап.`),5*n,[b('cos90°=0, поэтому поправочный член равен 0.','cos90°=0, сондықтан түзету мүшесі 0.'),b(`c²=${(3*n)**2}+${(4*n)**2}=${(5*n)**2},c=${5*n}.`,`c²=${(3*n)**2}+${(4*n)**2}=${(5*n)**2},c=${5*n}.`)],b('Косинусы здесь переходят в Пифагора.','Косинустар мұнда Пифагорға ауысады.')):l===2?num(b(`a=${2*n},A=30°,B=90°. Найди сторону b напротив B.`,`a=${2*n},A=30°,B=90°. B-ға қарсы b қабырғасын тап.`),4*n,[b('a/sin30°=b/sin90°;sin30°=1/2,sin90°=1.','a/sin30°=b/sin90°;sin30°=1/2,sin90°=1.'),b(`b=${2*n}·1/(1/2)=${4*n}.`,`b=${2*n}·1/(1/2)=${4*n}.`)],b('a и A должны быть противоположной парой.','a мен A қарсы жұп болуы тиіс.')):num(b(`Две стороны по ${n}, третья ${n}√2. Найди угол напротив третьей стороны в градусах.`,`Екі қабырға ${n}, үшіншісі ${n}√2. Үшіншіге қарсы бұрышты градуспен тап.`),90,[b(`(${n}√2)²=${n*n}+${n*n}−2·${n*n}cos C.`,`(${n}√2)²=${n*n}+${n*n}−2·${n*n}cos C.`),b('Получаем cos C=0; внутренний угол между 0° и 180°, значит C=90°.','cos C=0; ішкі бұрыш 0° пен 180° арасында, демек C=90°.')],b('Обратная проверка: квадрат третьей стороны равен сумме квадратов двух.','Кері тексеру: үшінші қабырға квадраты қалған екеуі квадраттарының қосындысына тең.')),
 },
 {
  id:'school-regular-polygons',grade:9,pathway:'common',quarter:3,appendix:54,pre:['school-sine-cosine-laws','circles','school-perimeter'],title:b('Правильные многоугольники','Дұрыс көпбұрыштар'),
  goal:b('Находить углы, периметр и связь стороны с радиусом, различая вписанную и описанную окружности.','Бұрыш, периметр және қабырға мен радиус байланысын табу, іштей және сырттай шеңберлерді ажырату.'),
  theory:b('Правильный многоугольник имеет одинаковые стороны и одинаковые внутренние углы. Центр соединяем с вершинами: получаются N равных треугольников, а полный угол 360° делится на N частей. Поэтому центральный угол равен 360°/N. Внешний поворот при обходе тоже 360°/N, внутренний угол дополняет его до 180°. Периметр — N одинаковых сторон. Описанная окружность проходит через вершины, её радиус R; вписанная касается сторон, её радиус r идёт перпендикулярно к середине стороны. Разделив один центральный треугольник пополам, получаем прямоугольный треугольник с гипотенузой R, катетом a/2 и углом π/N. Отсюда a=2R sin(π/N),r=R cos(π/N). Для калькулятора π/N означает радианы, а 180°/N — тот же угол в градусах: режимы нельзя смешивать. Все длины положительны,N — целое число не меньше трёх.','Дұрыс көпбұрыштың барлық қабырғасы мен ішкі бұрышы бірдей. Центрді төбелермен қоссақ,N тең үшбұрыш шығып, толық 360° бұрыш N бөлікке бөлінеді. Сондықтан центрлік бұрыш 360°/N. Айналып өткендегі сыртқы бұрылыс та 360°/N, ішкі бұрыш оны 180°-қа толықтырады. Периметр — N бірдей қабырға. Сырттай шеңбер төбелер арқылы өтеді, радиусы R; іштей шеңбер қабырғаларға жанасады, радиусы r қабырға ортасына перпендикуляр. Бір центрлік үшбұрышты тең бөлсек, гипотенузасы R, катеті a/2, бұрышы π/N тікбұрышты үшбұрыш аламыз. Осыдан a=2R sin(π/N),r=R cos(π/N). Калькуляторда π/N радиан,180°/N сол бұрыштың градус мәні: режимдерді араластырма. Барлық ұзындық оң,N — үштен кем емес бүтін сан.'),
  formula:b('α=180°−360°/N;P=Na;a=2R sin(π/N);S=Pr/2. α — внутренний угол,a — сторона,P — периметр,R и r — разные радиусы.','α=180°−360°/N;P=Na;a=2R sin(π/N);S=Pr/2. α — ішкі бұрыш,a — қабырға,P — периметр,R,r — әртүрлі радиустар.'),terms:b('Апофема здесь — перпендикуляр от центра к стороне, равный r; центральный угол расположен в центре.','Мұнда апофема — центрден қабырғаға перпендикуляр,r-ге тең; центрлік бұрыш центрде орналасады.'),method:b('Укажи число сторон и требуемый угол. Для длин выбери известный радиус, а не похожее обозначение. Проверь единицы и режим угла.','Қабырға санын және керек бұрышты ата. Ұзындықта ұқсас белгі емес, белгілі радиусты таңда. Бірліктер мен бұрыш режимін тексер.'),why:b('Равные центральные треугольники заполняют многоугольник без перекрытия; их площади a·r/2 складываются в P·r/2.','Тең центрлік үшбұрыштар көпбұрышты қабаттаспай толтырады; олардың a·r/2 аудандары P·r/2-ге қосылады.'),use:b('Форма плитки и симметричный чертёж. Текстовая модель — N равных треугольников вокруг центра.','Тақта пішіні және симметриялы сызба. Мәтіндік модель — центр айналасындағы N тең үшбұрыш.'),error:b('Центральный угол принят за внутренний либо R перепутан с r.','Центрлік бұрыш ішкі бұрыш деп алынған немесе R мен r шатасқан.'),
  build:(n,l)=>{const N=n+3;return l===1?num(b(`Найди внутренний угол правильного ${N}-угольника в градусах.`,`Дұрыс ${N}-бұрыштың ішкі бұрышын градуспен тап.`),180-360/N,[b(`Внешний поворот 360°/${N}.`,`Сыртқы бұрылыс 360°/${N}.`),b(`Внутренний 180°−360°/${N}=${f(180-360/N)}°.`,`Ішкі 180°−360°/${N}=${f(180-360/N)}°.`)],b('Все внешние повороты вместе составляют полный оборот.','Барлық сыртқы бұрылыс толық айналым құрайды.')):l===2?num(b(`Правильный ${N}-угольник имеет сторону ${2*n}. Найди периметр.`,`Дұрыс ${N}-бұрыш қабырғасы ${2*n}. Периметрін тап.`),2*n*N,[b(`Все ${N} сторон равны ${2*n}.`,`Барлық ${N} қабырға ${2*n}-ге тең.`),b(`P=${N}·${2*n}=${2*n*N}.`,`P=${N}·${2*n}=${2*n*N}.`)],b('Периметр складывает стороны, не радиусы.','Периметр радиустарды емес, қабырғаларды қосады.')):num(b(`Правильный ${N}-угольник вписан в окружность радиуса ${n+1}. Найди периметр; для вычисления синуса используй радианы.`,`Дұрыс ${N}-бұрыш радиусы ${n+1} шеңберге іштей сызылған. Периметрін тап; синусты есептеуде радиан қолдан.`),2*(n+1)*N*Math.sin(Math.PI/N),[b(`Половина стороны равна ${n+1}sin(π/${N}).`,`Қабырға жартысы ${n+1}sin(π/${N}).`),b(`P=2·${n+1}·${N}sin(π/${N})≈${f(2*(n+1)*N*Math.sin(Math.PI/N))}.`,`P=2·${n+1}·${N}sin(π/${N})≈${f(2*(n+1)*N*Math.sin(Math.PI/N))}.`)],b('Указан радиус описанной окружности R.','Сырттай шеңбердің R радиусы берілген.'));},
 },
 {
  id:'school-inverse-trig',grade:10,pathway:'natural-math',quarter:1,appendix:104,pre:['trig-circle','school-right-triangle-trig'],title:b('Обратные тригонометрические функции','Кері тригонометриялық функциялар'),
  goal:b('Находить главное значение arcsin и arccos и проверять его допустимый диапазон.','arcsin мен arccos басты мәнін табу және мүмкін аралығын тексеру.'),
  theory:b('Один синус повторяется у разных углов, поэтому обратная функция выбирает один специальный диапазон. arcsin t — угол от −π/2 до π/2 с синусом t;arccos t — угол от 0 до π с косинусом t. Для обеих функций вход t должен лежать от −1 до 1. arctan принимает любое действительное число и возвращает угол строго между −π/2 и π/2. arccot здесь определяем с главным значением от 0 до π; это соглашение нужно отмечать, потому что у разных учебных систем диапазоны бывают другими. Запись arcsin t не означает 1/sin t. Равенство arcsin(sinα)=α верно лишь для α в выбранном диапазоне; за его пределами возвращается другой угол с тем же синусом. Например, у 150° синус 1/2, но arcsin(1/2)=30°. В вычислениях различай градусы и радианы; формулы диапазонов чаще записаны в радианах.','Бір синус әртүрлі бұрышта қайталанады, сондықтан кері функция бір арнайы аралықты таңдайды. arcsin t — синусы t болатын −π/2 мен π/2 аралығындағы бұрыш;arccos t — косинусы t болатын 0 мен π аралығындағы бұрыш. Екі функцияның t кірісі −1 мен 1 арасында болуы тиіс. arctan кез келген нақты санды алып,−π/2 мен π/2 арасында қатаң жатқан бұрыш қайтарады. Мұнда arccot басты мәнін 0 мен π арасында анықтаймыз; басқа оқу жүйелерінде аралық өзгеше болуы мүмкін, сондықтан келісімді атау қажет. arcsin t жазуы 1/sin t емес. arcsin(sinα)=α теңдігі α таңдалған аралықта ғана дұрыс; сыртында дәл сол синусы бар басқа бұрыш қайтады. Мысалы,150° синусы 1/2, бірақ arcsin(1/2)=30°. Есептеуде градус пен радианды ажырат; аралық формулалары жиі радианмен жазылады.'),
  formula:b('arcsin:[−1;1]→[−π/2;π/2];arccos:[−1;1]→[0;π]. arctan:ℝ→(−π/2;π/2);arccot:ℝ→(0;π),cot=cos/sin. 180°=π радиан.','arcsin:[−1;1]→[−π/2;π/2];arccos:[−1;1]→[0;π]. arctan:ℝ→(−π/2;π/2);arccot:ℝ→(0;π),cot=cos/sin. 180°=π радиан.'),terms:b('Главное значение — выбранный единственный угол; область значений — диапазон возвращаемого угла;ℝ — все действительные числа. arctan t имеет тангенс t,arccot t — котангенс t.','Басты мән — таңдалған жалғыз бұрыш; мәндер жиыны — қайтарылатын бұрыш аралығы;ℝ — барлық нақты сандар. arctan t тангенсі t,arccot t котангенсі t.'),method:b('Определи функцию и её диапазон. Найди угол с нужным отношением внутри диапазона. Проверь функцию найденного угла, затем единицы ответа.','Функция мен оның аралығын анықта. Керек қатынасы бар бұрышты аралық ішінде тап. Табылған бұрыш функциясын, кейін жауап бірлігін тексер.'),why:b('Ограничение диапазона делает соответствие однозначным: на выбранной части значение каждой функции не повторяется.','Аралықты шектеу сәйкестікті бірмәнді етеді: таңдалған бөлікте әр функция мәні қайталанбайды.'),use:b('Восстановление угла по отношению сторон. Текстовая замена окружности — знак, известное значение и допустимый диапазон.','Қабырға қатынасынан бұрышты қалпына келтіру. Шеңбердің мәтіндік баламасы — таңба, белгілі мән және мүмкін аралық.'),error:b('Зачёркнуты sin и arcsin без проверки главного диапазона.','Басты аралық тексерілмей sin мен arcsin қысқартылған.'),
  build:(n,l)=>l===1?num(b(`Найди arcsin(sin(${n}π/12)). Ответ дай в градусах.`,`arcsin(sin(${n}π/12)) тап. Жауапты градуспен бер.`),15*n,[b(`Угол ${15*n}° находится в [−90°;90°].`,`${15*n}° бұрышы [−90°;90°] ішінде.`),b(`Главное значение совпадает: ${15*n}°.`,`Басты мән бірдей:${15*n}°.`)],b('У arcsin диапазон ограничен половиной окружности.','arcsin аралығы шеңбер жартысымен шектелген.')):l===2?match(b(`Сопоставь главные значения с градусами для θ=${n}π/12 и φ=${12-n}π/12, используя диапазоны урока. Здесь cot=cos/sin.`,`θ=${n}π/12 және φ=${12-n}π/12 үшін сабақ аралықтарын қолданып, басты мәндерді градуспен сәйкестендір. Мұнда cot=cos/sin.`),[{left:`arcsin(sin(${n}π/12))`,right:String(15*n)},{left:`arccos(cos(${n}π/6))`,right:String(30*n)},{left:`arctan(tan(${n}π/12))`,right:String(15*n)},{left:`arccot(cot(${12-n}π/12))`,right:String(180-15*n)}],[...new Set([String(15*n),String(30*n),String(180-15*n),String(-15*n)])],[b(`Для arcsin и arctan угол ${15*n}° допустим; для arccos угол ${30*n}° в [0°;180°].`,`arcsin,arctan үшін ${15*n}° мүмкін;arccos үшін ${30*n}° [0°;180°] ішінде.`),b(`Для принятого arccot угол ${180-15*n}° лежит в (0°;180°). У каждой функции своё главное значение.`,`Келісілген arccot үшін ${180-15*n}° (0°;180°) ішінде. Әр функцияның өз басты мәні бар.`)],b('Проверяй диапазон каждой функции отдельно.','Әр функция аралығын бөлек тексер.')):num(b(`Найди arcsin(sin(${n+6}π/12)). Ответ дай в градусах.`,`arcsin(sin(${n+6}π/12)) тап. Жауапты градуспен бер.`),15*(6-n),[b(`Исходный угол ${15*(n+6)}° выходит из диапазона arcsin.`,`Бастапқы ${15*(n+6)}° бұрыш arcsin аралығынан тыс.`),b(`sinα=sin(180°−α); главный угол 180°−${15*(n+6)}°=${15*(6-n)}°.`,`sinα=sin(180°−α); басты бұрыш 180°−${15*(n+6)}°=${15*(6-n)}°.`)],b('Нужен угол с тем же синусом между −90° и 90°.','−90° пен 90° арасындағы дәл сол синусы бар бұрыш керек.')),
 },
 {
  id:'school-random-variables',grade:10,pathway:'natural-math',quarter:4,appendix:104,pre:['probability','school-frequency-tables'],title:b('Случайная величина: ожидание и дисперсия','Кездейсоқ шама: күтім және дисперсия'),
  goal:b('Вычислять математическое ожидание и разброс дискретной величины, проверяя сумму вероятностей.','Дискрет шаманың математикалық күтімі мен шашырауын есептеу, ықтималдық қосындысын тексеру.'),
  theory:b('Случайная величина присваивает числовое значение каждому исходу: например, выигрыш или число успешных попыток. В дискретной таблице перечислены значения xᵢ и их вероятности pᵢ. Все pᵢ неотрицательны и суммируются в 1. Математическое ожидание E[X] — взвешенное среднее, весами служат вероятности. Оно описывает средний результат большого числа повторений модели, а не обязательный результат следующего опыта; ожидание может даже не быть одним из возможных значений. Дисперсия D[X] — средний квадрат отклонения от ожидания, поэтому неотрицательна. Удобна формула E[X²]−E[X]², но квадрат ожидания нельзя путать с ожиданием квадрата. Добавление одинаковой постоянной ко всем значениям сдвигает ожидание, но не меняет разброс. Умножение значений на c умножает дисперсию на c². Если X измеряется в тенге, дисперсия измеряется в квадратных тенге, а стандартное отклонение √D — снова в тенге.','Кездейсоқ шама әр нәтижеге сан береді: мысалы, ұтыс не сәтті әрекет саны. Дискрет кестеде xᵢ мәндері мен pᵢ ықтималдықтары тізілген. Барлық pᵢ теріс емес, қосындысы 1. E[X] математикалық күтімі — салмақтары ықтималдық болатын орташа. Ол модельді көп қайталаудың орта нәтижесін сипаттайды, келесі тәжірибенің міндетті нәтижесін емес; күтім мүмкін мәндердің бірі болмауы да мүмкін. D[X] дисперсиясы — күтімнен ауытқудың орта квадраты, сондықтан теріс емес. E[X²]−E[X]² формуласы ыңғайлы, бірақ күтім квадратын квадрат күтімімен шатастырма. Барлық мәнге бірдей тұрақты қосу күтімді жылжытады, шашырауды өзгертпейді. Мәндерді c-ға көбейту дисперсияны c²-қа көбейтеді. X теңгемен өлшенсе, дисперсия квадрат теңгемен, ал √D стандарт ауытқу қайта теңгемен өлшенеді.'),
  formula:b('E[X]=Σxᵢpᵢ;D[X]=Σ(xᵢ−E[X])²pᵢ=E[X²]−E[X]². Σpᵢ=1,pᵢ≥0.','E[X]=Σxᵢpᵢ;D[X]=Σ(xᵢ−E[X])²pᵢ=E[X²]−E[X]². Σpᵢ=1,pᵢ≥0.'),terms:b('Дискретная — значения можно перечислить; ожидание — взвешенный центр; дисперсия — средний квадрат разброса.','Дискрет — мәндерді тізуге болады; күтім — салмақталған орталық; дисперсия — шашыраудың орта квадраты.'),method:b('Проверь вероятности. Найди E[X]. Вычисли отклонения и их квадраты, взвесь вероятностями. Сверь со второй формулой и неотрицательностью.','Ықтималдықтарды тексер. E[X] тап. Ауытқулар мен квадраттарын есептеп, ықтималдықпен салмақта. Екінші формула және теріс еместікпен салыстыр.'),why:b('Возведение отклонений в квадрат не даёт положительным и отрицательным различиям взаимно уничтожиться. При одинаковом сдвиге отклонения остаются прежними.','Ауытқуды квадраттау оң және теріс айырмалардың өзара жойылуына жол бермейді. Бірдей жылжуда ауытқулар өзгермейді.'),use:b('Сравнение моделей риска и выигрыша. Расчёты верны для заданного распределения, которое в реальной ситуации ещё нужно обосновать.','Тәуекел мен ұтыс модельдерін салыстыру. Есеп берілген үлестірім үшін дұрыс; нақты жағдайда оны бөлек негіздеу керек.'),error:b('Использовано обычное среднее без весов или E[X²] заменено на E[X]².','Салмақсыз кәдімгі орта қолданылған немесе E[X²] орнына E[X]² алынған.'),
  build:(n,l)=>l===1?num(b(`X принимает 0 и ${2*n}, каждое с вероятностью 1/2. Найди E[X].`,`X 0 және ${2*n} мәнін әрқайсысын 1/2 ықтималдықпен алады. E[X]-ті тап.`),n,[b('Вероятности 1/2+1/2=1.','Ықтималдықтар 1/2+1/2=1.'),b(`E=0·1/2+${2*n}·1/2=${n}.`,`E=0·1/2+${2*n}·1/2=${n}.`)],b('Каждое значение умножается на свою вероятность.','Әр мән өз ықтималдығына көбейтіледі.')):l===2?num(b(`X принимает ${n} и ${3*n}, каждое с вероятностью 1/2. Найди D[X].`,`X ${n} және ${3*n} мәнін әрқайсысын 1/2 ықтималдықпен алады. D[X]-ті тап.`),n*n,[b(`E[X]=${2*n}; отклонения −${n} и ${n}.`,`E[X]=${2*n}; ауытқулар −${n} және ${n}.`),b(`D=${n*n}·1/2+${n*n}·1/2=${n*n}.`,`D=${n*n}·1/2+${n*n}·1/2=${n*n}.`)],b('Сначала центр, затем квадраты расстояний от него.','Алдымен орталық, кейін одан қашықтық квадраттары.')):match(b(`X принимает ${n} и ${n+2} с вероятностями 1/2;Y=X+5. Сопоставь характеристики и значения.`,`X ${n} және ${n+2} мәнін 1/2 ықтималдықпен алады;Y=X+5. Сипаттамалар мен мәндерді сәйкестендір.`),[{left:'E[X]',right:String(n+1)},{left:'D[X]',right:'1'},{left:'E[Y]',right:String(n+6)},{left:'D[Y]',right:'1'}],[String(n+1),'1',String(n+6),String(n+11)],[b(`E[X]=${n+1}; отклонения ±1 дают D[X]=1.`,`E[X]=${n+1};±1 ауытқулар D[X]=1 береді.`),b(`Сдвиг на 5 даёт E[Y]=${n+6}, но D[Y]=1.`,`5-ке жылжу E[Y]=${n+6} береді, бірақ D[Y]=1.`)],b('Сдвиг центра не изменяет расстояния между исходами.','Орталық жылжуы нәтижелер арасындағы қашықтықты өзгертпейді.')),
 },
 {
  id:'school-projections',grade:10,pathway:'common',quarter:2,appendix:106,alternateAppendices:[107],pre:['space-relations','triangles'],title:b('Проекция и три перпендикуляра','Проекция және үш перпендикуляр'),
  goal:b('Различать перпендикуляр, наклонную и её проекцию и применять теорему с точными условиями.','Перпендикуляр, көлбеу және оның проекциясын ажырату, теореманы дәл шарттармен қолдану.'),
  theory:b('Пусть S вне плоскости α,SO перпендикулярно α, а H — другая точка этой плоскости. SO — высота или расстояние от S до плоскости. SH — наклонная,OH — её ортогональная проекция. Треугольник SOH прямоугольный в O, поэтому SH²=SO²+OH². Высота короче любой наклонной с той же верхней точкой. Теорема о трёх перпендикулярах: если прямая l лежит в α и проходит через H, то l⊥OH тогда и только тогда, когда l⊥SH. Наличие одной линии в плоскости само по себе не гарантирует перпендикулярности наклонной. Важно, что OH — именно проекция данной SH, а не произвольный отрезок. Название напоминает о перпендикуляре SO к плоскости и двух связанных перпендикулярностях в H. Рисунок пространства может искажать углы: проверяй условия, а не видимость прямого угла на бумаге.','S α жазықтығынан тыс,SO оған перпендикуляр,H — жазықтықтың басқа нүктесі болсын. SO — биіктік не S-тен жазықтыққа қашықтық. SH — көлбеу,OH — оның ортогонал проекциясы. SOH үшбұрышы O-да тікбұрышты, сондықтан SH²=SO²+OH². Бір жоғарғы нүктеде биіктік кез келген көлбеуден қысқа. Үш перпендикуляр теоремасы:l түзуі α-да жатып,H арқылы өтсе,l⊥OH болуы l⊥SH болуына қажетті әрі жеткілікті. Түзудің тек жазықтықта жатуы көлбеуге перпендикулярлықты қамтамасыз етпейді. OH дәл SH проекциясы болуы маңызды, кез келген кесінді емес. Атау SO-ның жазықтыққа перпендикулярын және H-тегі байланысқан екі перпендикулярлықты еске салады. Кеңістік суреті бұрыштарды бұрмалайды: қағаздағы көріністі емес, шарттарды тексер.'),
  formula:b('SH²=SO²+OH²;SO⊥α,l⊂α,H∈l,O≠H: l⊥OH ⇔ l⊥SH.','SH²=SO²+OH²;SO⊥α,l⊂α,H∈l,O≠H:l⊥OH ⇔ l⊥SH.'),terms:b('Ортогональная проекция получается опусканием перпендикуляров;SO — перпендикуляр,SH — наклонная,OH — проекция.','Ортогонал проекция перпендикуляр түсірумен алынады;SO — перпендикуляр,SH — көлбеу,OH — проекция.'),method:b('Подпиши S,O,H и плоскость. Найди прямоугольный треугольник. Для теоремы проверь положение l, точку H и нужную проекцию.','S,O,H және жазықтықты ата. Тікбұрышты үшбұрышты тап. Теоремада l орны,H нүктесі және керек проекцияны тексер.'),why:b('Направление SH складывается из горизонтальной OH и вертикальной OS. Линия плоскости перпендикулярна OS автоматически; остаётся проверить горизонтальную часть.','SH бағыты көлденең OH пен тік OS-тен құралады. Жазықтық түзуі OS-ке автоматты перпендикуляр; көлденең бөлікті тексеру қалады.'),use:b('Наклонный трос и его длина на плане. Текстовая модель задаёт высоту SO, горизонтальную длину OH и соединяющую SH.','Көлбеу арқан және оның жоспардағы ұзындығы. Мәтіндік модель SO биіктігін,OH көлденең ұзындығын және қосатын SH-ты береді.'),error:b('Высота названа проекцией или использована теорема без условия l⊂α.','Биіктік проекция деп аталған немесе l⊂α шартынсыз теорема қолданылған.'),
  build:(n,l)=>l===1?num(b(`SO⊥α,SO=${3*n},OH=${4*n},O,H∈α. Найди SH.`,`SO⊥α,SO=${3*n},OH=${4*n},O,H∈α. SH-ты тап.`),5*n,[b('SOH прямоугольный в O.','SOH O-да тікбұрышты.'),b(`SH=√(${(3*n)**2}+${(4*n)**2})=${5*n}.`,`SH=√(${(3*n)**2}+${(4*n)**2})=${5*n}.`)],b('Наклонная — гипотенуза.','Көлбеу — гипотенуза.')):l===2?num(b(`SO⊥α,O,H∈α,SO=${3*n},SH=${5*n}. Найди длину проекции OH.`,`SO⊥α,O,H∈α,SO=${3*n},SH=${5*n}. OH проекция ұзындығын тап.`),4*n,[b('Квадрат проекции равен SH²−SO².','Проекция квадраты SH²−SO².'),b(`OH=√(${(5*n)**2}−${(3*n)**2})=${4*n}.`,`OH=√(${(5*n)**2}−${(3*n)**2})=${4*n}.`)],b('Гипотенуза больше высоты; вычитай в правильном порядке.','Гипотенуза биіктіктен үлкен; дұрыс ретпен азайт.')):choice(b(`SO⊥α,O,H∈α,SO=${3*n},OH=${4*n};l лежит в α и проходит через H. Какое условие гарантирует l⊥SH? A:l⊥OH;B:l∥OH;C: любая l в α;D: угол l с OH 45°.`,`SO⊥α,O,H∈α,SO=${3*n},OH=${4*n};l α-да жатып,H арқылы өтеді. Қай шарт l⊥SH-ты қамтамасыз етеді? A:l⊥OH;B:l∥OH;C:α-дағы кез келген l;D:l мен OH бұрышы 45°.`),'A',['A','B','C','D'],[b('OH — проекция SH, все условия теоремы выполнены.','OH — SH проекциясы, теорема шарттары орындалған.'),b('Перпендикулярность l проекции по теореме даёт перпендикулярность наклонной.','Теорема бойынша l-дің проекцияға перпендикулярлығы көлбеуге перпендикулярлық береді.')],b('Проверь проекцию и место линии перед выводом.','Қорытынды алдында проекция мен түзу орнын тексер.')),
 },
 {
  id:'school-space-equations',grade:10,pathway:'natural-math',quarter:4,appendix:106,pre:['space-vectors','school-plane-equations'],title:b('Уравнения плоскости, прямой и сферы','Жазықтық, түзу және сфера теңдеулері'),
  goal:b('Читать пространственную фигуру по уравнению и проверять все три координаты точки.','Кеңістіктегі фигураны теңдеуінен оқу және нүктенің үш координатасын тексеру.'),
  theory:b('В пространстве точка имеет три координаты (x;y;z). Плоскость Ax+By+Cz+D=0 задаётся ненулевой нормалью (A;B;C), перпендикулярной ей. Чтобы проверить точку, подставь все три числа. Сфера с центром (a;b;c) и радиусом R состоит из точек с квадратом расстояния R²:(x−a)²+(y−b)²+(z−c)²=R². Шар включает внутренность, сфера только поверхность. Прямая задаётся точкой P₀ и ненулевым направлением v: P=P₀+tv, где один и тот же параметр t используется во всех координатах. Подстановка разных t в x,y,z создаёт обычно точку вне прямой. Каноническая запись делит смещения на компоненты направления только там, где они ненулевые; при нулевой компоненте соответствующая координата постоянна. Уравнение плоскости можно умножить на ненулевое число, не меняя фигуру. Эти правила помогают отличать разные записи одной фигуры от разных объектов.','Кеңістікте нүктенің үш координатасы (x;y;z). Ax+By+Cz+D=0 жазықтығы оған перпендикуляр нөл емес (A;B;C) нормалімен беріледі. Нүктені тексеру үшін үш санын да қой. (a;b;c) центрі,R радиусы бар сфера қашықтық квадраты R² болатын нүктелерден тұрады:(x−a)²+(y−b)²+(z−c)²=R². Шар ішін қамтиды, сфера тек бет. Түзу P₀ нүктесі мен нөл емес v бағытымен беріледі:P=P₀+tv, бір t параметрі барлық координатада қолданылады. x,y,z-ке әртүрлі t қою әдетте түзуден тыс нүкте береді. Канондық жазу орын ауыстыруларды бағыттың нөл емес компонентіне ғана бөледі; нөл компонентте тиісті координата тұрақты. Жазықтық теңдеуін нөл емес санға көбейту фигураны өзгертпейді. Ережелер бір фигураның әр жазуын әртүрлі нысаннан ажыратуға көмектеседі.'),
  formula:b('Ax+By+Cz+D=0,(A;B;C)≠(0;0;0). P=P₀+tv,v≠0. Сфера:(x−a)²+(y−b)²+(z−c)²=R²,R>0.','Ax+By+Cz+D=0,(A;B;C)≠(0;0;0). P=P₀+tv,v≠0. Сфера:(x−a)²+(y−b)²+(z−c)²=R²,R>0.'),terms:b('Нормаль — перпендикулярное направление; параметр t — общее число, выбирающее точку прямой;R — радиус.','Нормаль — перпендикуляр бағыт;t параметрі — түзу нүктесін таңдайтын ортақ сан;R — радиус.'),method:b('Определи тип уравнения. Выдели центр/нормаль/направление. Подставляй координаты согласованно, проверяй ненулевые условия и одинаковый t.','Теңдеу түрін анықта. Центрді/нормальді/бағытты белгіле. Координаталарды үйлестіріп қой, нөл емес шарттар мен бірдей t-ны тексер.'),why:b('Нормаль проверяет смещение в перпендикулярном направлении; квадраты расстояний задают поверхность сферы; параметр перемещает точку вдоль одного направления.','Нормаль перпендикуляр бағыттағы орын ауыстыруды тексереді; қашықтық квадраттары сфера бетін береді; параметр нүктені бір бағытпен жылжытады.'),use:b('Координатная модель помещения и траектории. Свободный текст общего геометрического доказательства автоматически не проверяется.','Бөлме мен траекторияның координаталық моделі. Жалпы геометриялық дәлелдеудің еркін мәтіні автоматты тексерілмейді.'),error:b('У прямой использованы разные параметры или потеряна третья координата.','Түзуде әртүрлі параметр қолданылған немесе үшінші координата жоғалған.'),
  build:(n,l)=>l===1?num(b(`Найди радиус сферы (x−${n})²+(y−${n+1})²+(z−${n+2})²=${4*n*n}.`,`(x−${n})²+(y−${n+1})²+(z−${n+2})²=${4*n*n} сфера радиусын тап.`),2*n,[b('Правая часть равна R², не R.','Оң жақ R², R емес.'),b(`R=√${4*n*n}=${2*n}.`,`R=√${4*n*n}=${2*n}.`)],b('Радиус положителен.','Радиус оң.')):l===2?num(b(`Точка (${n};${n};z) лежит в плоскости x+2y+3z=${6*n}. Найди z.`,`(${n};${n};z) нүктесі x+2y+3z=${6*n} жазықтығында. z-ті тап.`),n,[b(`Подстановка даёт ${n}+${2*n}+3z=${6*n}.`,`Қою ${n}+${2*n}+3z=${6*n} береді.`),b(`3z=${3*n},z=${n}.`,`3z=${3*n},z=${n}.`)],b('В уравнение входят все координаты.','Теңдеуге барлық координата кіреді.')):match(b(`Прямая (x;y;z)=(${n};1;2)+t(2;3;4). Сопоставь координаты при t=${n} с числами.`,`(x;y;z)=(${n};1;2)+t(2;3;4) түзуі. t=${n} кезінде координаталарды сандармен сәйкестендір.`),[{left:'x',right:String(3*n)},{left:'y',right:String(3*n+1)},{left:'z',right:String(4*n+2)}],[String(3*n),String(3*n+1),String(4*n+2),String(n)],[b(`x=${n}+2·${n};y=1+3·${n};z=2+4·${n}.`,`x=${n}+2·${n};y=1+3·${n};z=2+4·${n}.`),b('Один t применяется к трём компонентам направления.','Бір t бағыттың үш компонентіне қолданылады.')],b('Число перед t зависит от координаты, сам t общий.','t алдындағы сан координатаға тәуелді,t-ның өзі ортақ.')),
 },
 {
  id:'school-sampling',grade:7,pathway:'common',quarter:2,appendix:53,pre:['school-frequency-tables','school-decimals'],title:b('Выборка и вариационный ряд','Таңдама және вариациялық қатар'),
  goal:b('Отличать выборку от всей исследуемой группы, упорядочивать данные и замечать смещение отбора.','Таңдаманы бүкіл зерттелетін топтан ажырату, деректерді реттеу және іріктеу ығысуын байқау.'),
  theory:b('Генеральная совокупность — все объекты, о которых хотим узнать; выборка — те, кого действительно исследовали. Если изучаем всех учеников школы, опрос только одной секции не становится автоматически представительным: у её участников могут быть другие привычки. Случайный отбор из всей группы снижает систематическое смещение, но не гарантирует точного результата в одной небольшой выборке. Варианта — одно наблюдаемое значение. Вариационный ряд располагает значения по возрастанию, сохраняя повторы; удалять повторяющиеся результаты нельзя. В таком ряду легко увидеть минимум, максимум и медиану. При чётном числе наблюдений медиана — среднее двух центральных значений; при нечётном — одно центральное. Размах равен максимуму минус минимуму. Отсутствующее наблюдение отличается от измеренного нуля: вносить ноль без основания нельзя. Для выводов важны и размер выборки, и способ её получения.','Бас жиынтық — білгіміз келетін барлық нысан; таңдама — нақты зерттелгендері. Мектептің барлық оқушысын зерттесек, тек бір үйірмені сұрау автоматты өкілдік бермейді: қатысушылар әдеттері өзгеше болуы мүмкін. Бүкіл топтан кездейсоқ іріктеу жүйелі ығысуды азайтады, бірақ жалғыз шағын таңдамада дәл нәтижеге кепіл емес. Варианта — бір бақыланған мән. Вариациялық қатар мәндерді өсу ретімен, қайталануларын сақтап қояды; қайталанған нәтижелерді алып тастауға болмайды. Мұндай қатарда минимум, максимум және медиана көрінеді. Бақылау саны жұп болса медиана орталық екі мәннің ортасы; тақ болса бір орталық мән. Құлаш максимумнан минимумды азайтуға тең. Жоқ бақылау өлшенген нөлден өзгеше: негізсіз нөл жазуға болмайды. Қорытындыға таңдама көлемі де, оны алу тәсілі де маңызды.'),
  formula:b('Размах=max−min. Для упорядоченных четырёх значений медиана=(x₂+x₃)/2. xᵢ — значение на месте i.','Құлаш=max−min. Реттелген төрт мән үшін медиана=(x₂+x₃)/2. xᵢ — i орнындағы мән.'),terms:b('Выборка — часть совокупности; вариационный ряд — упорядоченные наблюдения; смещение — систематический перекос отбора.','Таңдама — жиынтық бөлігі; вариациялық қатар — реттелген бақылаулар; ығысу — іріктеудің жүйелі ауытқуы.'),method:b('Назови всю исследуемую группу и способ отбора. Упорядочь результаты с повторами. Выбери нужную характеристику и отметь ограниченность вывода.','Бүкіл зерттелетін топ пен іріктеу тәсілін ата. Нәтижелерді қайталаумен ретте. Керек сипаттаманы таңдап, қорытынды шектеуін белгіле.'),why:b('Ряд меняет только порядок, не сами данные, поэтому сохраняет информацию о повторениях. Случайный выбор не выделяет заранее удобную подгруппу.','Қатар деректердің өзін емес, тек ретін өзгертеді, сондықтан қайталану ақпараты сақталады. Кездейсоқ таңдау алдын ала ыңғайлы шағын топты бөліп алмайды.'),use:b('Школьный опрос о времени дороги. Автоматически проверяется выбор метода, но статистический вывод по реальным данным требует анализа качества сбора.','Мектептегі жол уақыты сауалнамасы. Тәсіл таңдау автоматты тексеріледі, бірақ нақты дерек қорытындысы жинау сапасын талдауды қажет етеді.'),error:b('Медиана найдена до упорядочивания или удобная подгруппа объявлена всей совокупностью.','Медиана реттеуге дейін табылған немесе ыңғайлы шағын топ бүкіл жиынтық деп алынған.'),
  build:(n,l)=>l===1?num(b(`Данные:${n+3},${n},${n+1},${n+2}. Найди медиану.`,`Деректер:${n+3},${n},${n+1},${n+2}. Медиананы тап.`),n+1.5,[b(`Ряд:${n},${n+1},${n+2},${n+3}.`,`Қатар:${n},${n+1},${n+2},${n+3}.`),b(`Медиана (${n+1}+${n+2})/2=${n+1.5}.`,`Медиана (${n+1}+${n+2})/2=${n+1.5}.`)],b('При четырёх значениях два центральных.','Төрт мәнде орталық екеу.')):l===2?num(b(`Найди размах наблюдений ${n+3},${n},${n+1},${n+2}.`,` ${n+3},${n},${n+1},${n+2} бақылауларының құлашын тап.`),3,[b(`Максимум ${n+3}, минимум ${n}.`,`Максимум ${n+3}, минимум ${n}.`),b(`Размах ${n+3}−${n}=3.`,`Құлаш ${n+3}−${n}=3.`)],b('Для размаха нужны крайние, а не средние значения.','Құлашқа орта емес, шеткі мәндер керек.')):choice(b(`Хотим узнать время дороги всех ${4*n+20} учеников класса, опрашиваем ${n+5}. Какой отбор лучше избегает выделения удобной подгруппы? A: случайно из полного списка;B: первые пришедшие;C: только спортсмены;D: только живущие рядом.`,`Сыныптың барлық ${4*n+20} оқушысының жол уақытын білгіміз келеді,${n+5} оқушыны сұраймыз. Қай іріктеу ыңғайлы шағын топты бөліп алудан жақсырақ сақтайды? A: толық тізімнен кездейсоқ;B: алғаш келгендер;C: тек спортшылар;D: тек жақын тұратындар.`),'A',['A','B','C','D'],[b('Полный список соответствует генеральной совокупности.','Толық тізім бас жиынтыққа сәйкес.'),b('Случайный отбор не выделяет привычки или место жительства, но погрешность небольшой выборки остаётся.','Кездейсоқ іріктеу әдет не тұрғылықты жерді бөлмейді, бірақ шағын таңдама қатесі қалады.')],b('Способ отбора важен не меньше числа участников.','Іріктеу тәсілі қатысушы санынан кем маңызды емес.')),
 },
 {
  id:'school-truncated-solids',grade:11,pathway:'common',quarter:3,appendix:106,alternateAppendices:[107],pre:['cones','pyramids','cylinders','spheres'],title:b('Усечённые и составные тела','Қиық және құрама денелер'),
  goal:b('Выбирать формулу усечённого тела и складывать объёмы неперекрывающихся частей, не считая общий контакт дважды.','Қиық дене формуласын таңдау және қабаттаспайтын бөліктер көлемін қосу, ортақ жанасуды екі рет санамау.'),
  theory:b('Усечённый конус получается срезом обычного конуса плоскостью, параллельной основанию. Два радиуса R и r различаются, а высота h — перпендикулярное расстояние между основаниями, не образующая. Объём равен πh(R²+Rr+r²)/3, он не равен объёму цилиндра со средним радиусом. Усечённая пирамида имеет параллельные подобные основания; их площади S₁,S₂ дают V=h(S₁+√(S₁S₂)+S₂)/3. Подобие и параллельность здесь обязательны: формула не описывает любой объект с двумя основаниями. В составном теле мысленно раздели части на знакомые тела. Если внутренности не перекрываются, объёмы складываются; общий диск стыка не имеет объёма. Для наружной площади этот диск, наоборот, нужно убрать из суммы поверхностей. Полусфера имеет половину объёма шара, но её полная поверхность дополнительно содержит основание. Перед вычислением нарисуй или опиши разбиение и проверь единицы.','Қиық конус кәдімгі конусты негізіне параллель жазықтықпен кескенде шығады. R,r радиустары әртүрлі,h биіктігі — негіздер арасындағы перпендикуляр қашықтық, жасаушы емес. Көлем πh(R²+Rr+r²)/3, ол орта радиусты цилиндр көлеміне тең емес. Қиық пирамиданың негіздері параллель және ұқсас;S₁,S₂ аудандары V=h(S₁+√(S₁S₂)+S₂)/3 береді. Ұқсастық пен параллельдік міндетті: формула екі негізі бар кез келген нысанды сипаттамайды. Құрама денені таныс денелерге ойша бөл. Іштері қабаттаспаса көлемдер қосылады; түйісу дөңгелегінің көлемі жоқ. Ал сыртқы аудан үшін бұл дөңгелек беттер қосындысынан алынады. Жарты шар шар көлемінің жартысын береді, бірақ толық бетіне негізі де қосылады. Есептер алдында бөлуді сыз не сипаттап, бірліктерді тексер.'),
  formula:b('Конус V=πh(R²+Rr+r²)/3; пирамида V=h(S₁+√(S₁S₂)+S₂)/3. Полушар V=2πr³/3.','Қиық конус V=πh(R²+Rr+r²)/3; қиық пирамида V=h(S₁+√(S₁S₂)+S₂)/3. Жарты шар V=2πr³/3.'),terms:b('R,r — радиусы оснований;S₁,S₂ — площади подобных оснований;h — высота; составное тело объединяет части.','R,r — негіз радиустары;S₁,S₂ — ұқсас негіз аудандары;h — биіктік; құрама дене бөліктерді біріктіреді.'),method:b('Подпиши основания и высоту. Выбери конус или пирамиду, не смешивая длины и площади. Для комбинации обозначь части и их общий стык.','Негіздер мен биіктікті ата. Ұзындық пен ауданды араластырмай, конус не пирамиданы таңда. Құрамда бөліктер мен ортақ түйісуді белгіле.'),why:b('Параллельные сечения подобных тел меняются закономерно; сумма объёмов сохраняется при разбиении без перекрытия. Нулевой толщины контакт не добавляет объёма.','Ұқсас денелердің параллель қималары заңды өзгереді; қабаттаспай бөлгенде көлем қосындысы сақталады. Қалыңдығы нөл түйісу көлем қоспайды.'),use:b('Ёмкость и купольная конструкция. Проверяемые задачи посвящены объёму; полные развёртки и наружные площади сложных комбинаций требуют дополнительных упражнений.','Ыдыс және күмбез құрылымы. Тексерілетін есептер көлемге арналған; күрделі құрамдардың толық жазбасы мен сыртқы ауданына қосымша жаттығу керек.'),error:b('Высота заменена образующей или объёмы сложены при перекрывающихся внутренних частях.','Биіктік жасаушымен ауыстырылған немесе іші қабаттасатын бөліктер көлемі қосылған.'),
  build:(n,l)=>l===1?num(b(`Усечённый конус:R=${2*n},r=${n},h=3. Найди V/π.`,`Қиық конус:R=${2*n},r=${n},h=3. V/π тап.`),7*n*n,[b(`V/π=(3/3)(${4*n*n}+${2*n*n}+${n*n}).`,`V/π=(3/3)(${4*n*n}+${2*n*n}+${n*n}).`),b(`V/π=${7*n*n}.`,`V/π=${7*n*n}.`)],b('В формуле присутствует среднее произведение Rr.','Формулада орта көбейтінді Rr бар.')):l===2?num(b(`Усечённая пирамида с параллельными подобными основаниями площадей ${n*n} и ${4*n*n},h=3. Найди объём.`,`Қиық пирамиданың параллель ұқсас негіз аудандары ${n*n} және ${4*n*n},h=3. Көлемін тап.`),7*n*n,[b(`√(S₁S₂)=√${4*n**4}=${2*n*n}.`,`√(S₁S₂)=√${4*n**4}=${2*n*n}.`),b(`V=(3/3)(${n*n}+${2*n*n}+${4*n*n})=${7*n*n}.`,`V=(3/3)(${n*n}+${2*n*n}+${4*n*n})=${7*n*n}.`)],b('Под корнем произведение площадей, не сумма.','Түбір астында аудан көбейтіндісі, қосынды емес.')):num(b(`Цилиндр радиуса ${n}, высоты 3 соединён по основанию с полушаром того же радиуса, внутренности не пересекаются. Найди V/π.`,`Радиусы ${n}, биіктігі 3 цилиндр сол радиусты жарты шармен негізі арқылы жалғасқан, іштері қиылыспайды. V/π тап.`),3*n*n+2*n**3/3,[b(`Vцил/π=3·${n}²=${3*n*n};Vполушара/π=2·${n}³/3.`,`Vцилиндр/π=3·${n}²=${3*n*n};Vжарты шар/π=2·${n}³/3.`),b(`Общий объём/π=${3*n*n}+${2*n**3}/3=${f(3*n*n+2*n**3/3)}.`,`Жалпы көлем/π=${3*n*n}+${2*n**3}/3=${f(3*n*n+2*n**3/3)}.`)],b('Общий диск не имеет толщины и не добавляет объём.','Ортақ дөңгелектің қалыңдығы жоқ, көлем қоспайды.')),
 },
];

