 const supportingIds=new Set(['school-basic-angles','school-number-ray','school-perimeter','units','school-coordinate-plane','linear-systems','school-polynomials','factoring','school-frequency-tables','school-decimals','triangles','fractions','functions','linear-inequalities','arithmetic','geometric','radicals','circles','trig-circle','probability','space-relations','space-vectors','cones','pyramids','cylinders','spheres','integral']);
