  const check=(valid:boolean,label:string)=>{if(!valid)errors.push(`${topic.id}: ${label}`);};
  check(topic.track==='base'&&topic.spec===null,'School-only topic must not claim an ENT specification');
  check(topic.minutes>=10&&topic.minutes<=15,'Lesson duration estimate');
  check(bilingualPresent(topic.title)&&bilingualPresent(topic.description),'Bilingual title/description');
  const lesson=topic.lesson;
  for(const key of ['goal','explanation','simpler','formula','terms'] as const)check(bilingualPresent(lesson[key]),`Bilingual ${key}`);
  check(lesson.explanation.ru.length>=450&&lesson.explanation.kk.length>=450,'Substantive explanation');
  check(lesson.blocks.length>=3&&lesson.blocks.every(v=>bilingualPresent(v.title)&&bilingualPresent(v.body)),'Bilingual teaching blocks');
  check(lesson.examples.length>=3&&lesson.examples.every(v=>bilingualPresent(v.problem)&&v.steps.ru.length>=2&&v.steps.kk.length>=2&&Boolean(v.answer)),'Worked examples');
  check(bilingualPresent(lesson.guided.problem)&&lesson.guided.steps.ru.length>=2&&lesson.guided.steps.kk.length>=2,'Guided problem');
  check(bilingualPresent(lesson.checkpoint.question)&&bilingualPresent(lesson.checkpoint.answer)&&bilingualPresent(lesson.checkpoint.why),'Understanding checkpoint');
  check(lesson.mistakes.ru.length>=2&&lesson.mistakes.kk.length>=2&&lesson.recap.ru.length>=2&&lesson.recap.kk.length>=2,'Mistakes/recap');
  check(topic.tasks.length>=15&&[1,2,3].every(l=>topic.tasks.filter(t=>t.level===l).length>=5),'Fifteen tasks at three levels');
  [0,5,10].forEach((index,i)=>check(JSON.stringify(lesson.examples[i])===JSON.stringify(example(topic.tasks[index])),'Reserved worked-example indices'));
  check(JSON.stringify(lesson.guided)===JSON.stringify(example(topic.tasks[1])),'Reserved guided index');
  check(JSON.stringify(lesson.checkpoint.question)===JSON.stringify(topic.tasks[2].prompt),'Reserved checkpoint index');
